<?php
declare(strict_types=1);
require_once __DIR__.'/tenant.php';
require_once __DIR__ . '/auth.php';

$loginError='';
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='logout') { verifyCsrf(); logout(); header('Location: ./'); exit; }
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='login') {
    $ok=attemptLogin((string)($_POST['username']??''),(string)($_POST['password']??''));
    if($ok){ header('Location: ./'); exit; }
    $loginError='Gebruikersnaam of wachtwoord is onjuist.';
}
$user=currentUser();
if($user && !empty($user['must_change_password'])){header('Location: change_password.php');exit;}
$loginNotice=(string)($_SESSION['login_notice']??'');
unset($_SESSION['login_notice']);
if(!$user && $loginError==='' && $loginNotice!=='') $loginError=$loginNotice;
$appVersion='v8.50';
