<script>
let detailRequest=0;
const USER_ROLE=<?=json_encode((string)$user['role'])?>;let listEntity='contacts',currentEntity=null,rows=[],selected=null,meta=null,timer=null,historyStack=[],deepContact=null,deepRelation=null,pendingParent=null;const $=id=>document.getElementById(id);function syncListHeader(){const h=document.querySelector('.detail-head'),p=document.querySelector('.panel-head');if(h&&p&&window.innerWidth>760)p.style.minHeight=h.offsetHeight+'px';else if(p)p.style.minHeight='96px'}window.addEventListener('resize',syncListHeader);const esc=v=>String(v??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]));const normKey=k=>String(k??'').toLowerCase().replace(/[^a-z0-9]/g,'');const findKey=(o,keys)=>{if(!o)return null;const wanted=keys.map(normKey);for(const k of Object.keys(o)){if(wanted.includes(normKey(k)))return k}return null};const first=(o,keys)=>{const k=findKey(o,keys);return k&&o[k]!=null&&o[k]!==''?o[k]:''};
function pk(e){return meta.entities[e].primary}function isIdField(k){const n=normKey(k);return n==='id'||n.endsWith('id')}
function label(k){const m={VergaderingID:'Vergadering-ID',Datum:'Datum',Soort:'Soort',Locatie:'Locatie',Aanwezig:'Aanwezig',Agenda:'Agenda',Verslag:'Verslag',ActieID:'Actie-ID',VergaderingID:'Vergadering-ID',Actie:'Actie',Verantwoordelijk:'Verantwoordelijk',Omschrijving:'Omschrijving',DatumCompleet:'Datum gereed',Compleet:'Gereed',OnderhoudsplanID:'Onderhoudsplan-ID',Planjaar:'Planjaar',UitvoeringsJaar:'Uitvoeringsjaar',DatumInspectie:'Datum inspectie',Indexering:'Indexering',PlanBedrag:'Planbedrag',OnderhoudsCategorie:'Onderhoudscategorie',StabuCode:'STABU-code',MJOPReferentie:'MJOP referentie',Uitvoerder:'Uitvoerder',Werkomschrijving:'Werkomschrijving',Documenten:'Documenten',ContactID:'Contact-ID',RelatieID:'Relatie-ID',Id:'Adres-ID',ActivaID:'Activa-ID',Huisnummer:'Huisnummer',Hal:'Hal',Aanhef:'Aanhef',AchterNaam:'Achternaam',Tussenvoegsel:'Tussenvoegsel',Voorletters:'Voorletters',VoorNaam:'Voornaam',Toevoegsel:'Toevoegsel',VVELid:'VvE-lid',Bestuurslid:'Bestuurslid',VVEFunctie:'VvE-functie',Nieuwsbrief:'Nieuwsbrief',Jaarverslag:'Jaarverslag',TestAccount:'Testaccount',Notities:'Opmerkingen',Huurder:'Huurder',Bewoner:'Bewoner',Eigenaar:'Eigenaar',Verhuurder:'Verhuurder',Derden:'Derden',Actief:'Actief',Update:'Laatste bronwijziging',Bergingsgang:'Bergingsgang',Servicekosten:'Servicekosten',Appartementsgrootte:'Appartementsgrootte',Bijlagen:'Bijlagen',Etage:'Etage',Naam:'Naam',Sinds:'Sinds',AdresSoort:'Soort adres',NaamSleutelhouder:'Naam sleutelhouder',SleutelID:'Sleutel-ID',Functie:'Functie',Omschrijving:'Omschrijving',Verantwoordelijk:'Verantwoordelijk',Merk:'Merk',Sleutelnummer:'Sleutelnummer',Locatie:'Locatie',UitgeleendAan:'Uitgeleend aan',Uitleendatum:'Uitleendatum',Retourdatum:'Retourdatum',Straat:'Straat',Postcode:'Postcode',Woonplaats:'Woonplaats',Mobiel:'Mobiel',TelefoonHuis:'Telefoon huis',EmailPrive:'E-mail privé',EmailWerk:'E-mail werk',Land:'Land',Postbus:'Postbus',TelefoonWerk:'Telefoon werk',Fax:'Fax',Facebook:'Facebook',Twitter:'Twitter',LinkedIn:'LinkedIn',Website:'Website',Titel:'Titel','Tag Geel':'Tag geel','Tag Oranje':'Tag oranje','Tag Blauw':'Tag blauw','Tag Rood':'Tag rood','Tag Groen':'Tag groen','Tag Grijs Rood':'Tag grijs rood','WIFI Terminal':'WIFI terminal', 'Bewoner: AchterNaam':'Bewoner achternaam','Bewoner: VoorNaam':'Bewoner voornaam','Bewoner: Voorletters':'Bewoner voorletters','Bewoner: Tussenvoegsel':'Bewoner tussenvoegsel','Bewoner: Toevoegsel':'Bewoner toevoegsel',CategorieID:'Categorie-ID',SoortID:'Soort-ID',Alias:'Alias',ActivaCatID:'Categorie',ParentActivaID:'Onderdeel van',VerantwoordelijkTCLid:'Verantwoordelijk TC-lid','Afschrijftermijn Jaren':'Afschrijftermijn','Afgeschreven Jaren':'Afgeschreven','Af te schrijven':'Af te schrijven','Huidige boekwaarde':'Huidige Boekwaarde','Aanschafwaarde':'Aanschafwaarde','Aanschafdatum':'Aanschafdatum','Datum ingebruikname':'Ingebruikname datum','BTW Nummer':'BTW-nummer',KvKNummer:'KvK-nummer',BankRelatie:'IBAN',BIC:'BIC',SEPAMachtiging:'SEPA-machtiging',IBAN:'IBAN',SharePointLink:'SharePoint-link'};if(m[k])return m[k];const nk=normKey(k);for(const [mk,mv] of Object.entries(m))if(normKey(mk)===nk)return mv;return k}
function name(c){return [first(c,['Aanhef']),first(c,['VoorNaam']),first(c,['Voorletters']),first(c,['Tussenvoegsel']),first(c,['AchterNaam'])].filter(Boolean).join(' ')||('Contact '+(c?.[pk('contacts')]??''))}
function addressContactName(a){const cid=first(a,['ContactID','Bewoner_ContactID','contact_id','bewoner_contact_id']);const c=cid?rows.find(x=>String(x[pk('contacts')])===String(cid)):null;return c?name(c):''}
async function api(path,opts={}){const h={'Accept':'application/json',...(opts.headers||{})};if(opts.body && !(opts.body instanceof FormData))h['Content-Type']='application/json';if(meta?.csrf)h['X-CSRF-Token']=meta.csrf;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),10000);try{const sep=path.includes('?')?'&':'?';const r=await fetch('api.php'+path+sep+'_v=7.82&ts='+Date.now(),{...opts,headers:h,cache:'no-store',credentials:'same-origin',signal:controller.signal});const t=await r.text();let d;try{d=JSON.parse(t)}catch(e){throw new Error('Server gaf geen JSON terug (HTTP '+r.status+'). Eerste antwoord: '+t.slice(0,300))}if(!r.ok||d.ok===false)throw new Error(d.error||('HTTP '+r.status));return d}catch(e){if(e.name==='AbortError')throw new Error('Verbinding met api.php time-out na 10 seconden.');throw new Error('API-verbindingsfout: '+(e.message||e))}finally{clearTimeout(timeout)}}
function currentTableColumns(){if(listEntity==='Sleutels'&&typeof keyColumns==='function')return keyColumns();if(listEntity==='Activa'&&typeof assetEditableColumns==='function')return assetEditableColumns(selected||{}).filter(k=>!assetExcluded(k));if(listEntity==='maintenance_plans'&&typeof maintenanceColumns==='function')return maintenanceColumns();if(listEntity==='contacts'||listEntity==='relations')return orderedColumns(listEntity,meta?.entities?.[listEntity]?.columns||[]).filter(k=>!isHiddenField(k,listEntity));if(listEntity==='meetings')return ['Datum','Soort','Locatie','Aanwezig','Agenda','Verslag','Actief'].filter(k=>(meta?.entities?.meetings?.columns||[]).some(c=>normKey(c)===normKey(k)));return meta?.entities?.[listEntity]?.columns||[]}
function currentTableTitle(){return listEntity==='contacts'?'Contacten':listEntity==='addresses'?'Adressen':listEntity==='maintenance_plans'?'Onderhoudsplannen':listEntity==='meetings'?'Vergaderingen':listEntity==='actions'?'ActieRegister':listEntity==='Sleutels'?'Sleutels':'Relaties'}
function tableCellValue(entity,r,k){let v=r?.[k]??'';if(entity==='Sleutels'){if(normKey(k)==='activaid'&&v)v=keyAssetName(v);if(isDateFieldName(k))v=dateDisplayValue(v)}return v}
function buildTableHtml(){const cols=currentTableColumns();const title=currentTableTitle();const body=rows.map(r=>'<tr>'+cols.map(k=>'<td>'+esc(tableCellValue(listEntity,r,k))+'</td>').join('')+'</tr>').join('');return '<table class="data-table"><thead><tr>'+cols.map(k=>'<th>'+esc(label(k))+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table>'}
async function openTableView(){if(!meta)return;const btn=$('tableViewBtn');if(btn){btn.disabled=true;btn.textContent='⏳ Laden…'}try{const q=encodeURIComponent($('search')?.value.trim()||'');const status=encodeURIComponent($('statusFilter')?.value||'active');const d=await api('?action=list&entity='+encodeURIComponent(listEntity)+'&q='+q+'&status='+status);rows=d.rows||[];sortRows();const cols=currentTableColumns();$('audit').hidden=true;$('detailTitle').textContent='Lijstweergave — '+currentTableTitle();$('detailSub').textContent=rows.length+' record(s) · '+cols.length+' velden · '+($('statusFilter')?.selectedOptions?.[0]?.text||'Actief');$('detail').innerHTML='<div class="listview-toolbar"><div><strong>'+esc(currentTableTitle())+'</strong><span class="muted"> — alle velden</span></div><div class="listview-actions"><button class="btn" type="button" onclick="exportCurrentCsv()">⬇ CSV</button><button class="btn" type="button" onclick="exportCurrentPdf()">⬇ PDF</button><button class="btn" type="button" onclick="closeRightListView()">✕ Sluiten</button></div></div><div class="right-table-wrap">'+(rows.length?buildTableHtml():'<div class="pad muted">Geen records in de huidige selectie.</div>')+'</div>';$('detail').dataset.listview='1';syncListHeader()}catch(e){$('detail').innerHTML='<div class="err">Lijstweergave kon niet worden geopend: '+esc(e.message)+'</div>'}finally{if(btn){btn.disabled=false;btn.textContent='☷ Lijstweergave'}}}
function closeTableView(){$('tableModal').classList.remove('open');document.body.style.overflow=''}
function closeRightListView(){delete $('detail').dataset.listview;$('detailTitle').textContent='Selecteer een record';$('detailSub').textContent='';$('audit').hidden=true;$('detail').innerHTML='<div class="notice">Selecteer links een contact of relatie. Adressen zijn uitsluitend via een contact of relatie bereikbaar.</div>';selected=null;syncListHeader()}
function csvCell(v){const x=String(v??'').replace(/"/g,'""');return '"'+x+'"'}
function exportCurrentCsv(){const cols=currentTableColumns();if(!cols.length)return;const lines=[cols.map(k=>csvCell(label(k))).join(';')];for(const r of rows)lines.push(cols.map(k=>csvCell(tableCellValue(listEntity,r,k))).join(';'));const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=currentTableTitle().toLowerCase()+'_'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportCurrentPdf(){
  const title='VvE Beheer — '+currentTableTitle();
  const html=buildTableHtml();
  const w=window.open('','_blank','width=1600,height=1000');
  if(!w){alert('Het PDF-venster kon niet worden geopend. Sta pop-ups voor deze pagina toe.');return}
  const css=`@page{size:landscape;margin:10mm}
body{font:8px Arial,sans-serif;color:#17202a}
h1{font-size:16px;margin:0 0 4px}
p{font-size:9px;color:#667482;margin:0 0 8px}
