function meetingPk(){return meta.entities.meetings.primary}
function meetingDateDisplay(v){return dateDisplayValue(v)}
function meetingInputDate(v){return dateInputValue(v)}
function meetingTitle(r){return (meetingDateDisplay(first(r,['Datum']))||'Nieuwe vergadering')+' · '+(first(r,['Soort'])||'Vergadering')}
function meetingSub(r){return [first(r,['Locatie']),first(r,['Aanwezig'])].filter(Boolean).join(' · ')}
function meetingStatusValue(r){return first(r,['Actief'])||'Waar'}
function meetingSortRows(){const mode=$('sortFilter')?.value||'date_desc';rows.sort((a,b)=>{const av=meetingInputDate(first(a,['Datum']))||'';const bv=meetingInputDate(first(b,['Datum']))||'';return mode==='date_asc'?av.localeCompare(bv):bv.localeCompare(av)})}
function meetingListPlaceholders(){ $('listTitle').textContent='Vergaderingen'; const sh=$('search'); if(sh)sh.placeholder='Zoek datum, soort, locatie of vergadertekst'; const q=$('question');if(q)q.placeholder='Bijv. welke vergadering was op 09-09-2026?'; const sf=$('sortFilter');if(sf){sf.innerHTML='<option value="date_desc">Datum nieuw → oud</option><option value="date_asc">Datum oud → nieuw</option>';if(!['date_desc','date_asc'].includes(sf.value))sf.value='date_desc';} const tv=$('tableViewBtn');if(tv){tv.textContent='📄 Verslag + acties';tv.onclick=openMeetingReport}}
function renderMeetingStatus(){const sf=$('statusFilter');if(!sf)return;sf.innerHTML='<option value="active">Actief</option><option value="inactive">Niet actief</option><option value="__all__">Alle</option>';if(!['active','inactive','__all__'].includes(sf.value))sf.value='active'}
async function loadMeetings(){currentEntity='meetings';meetingListPlaceholders();renderMeetingStatus();try{const q=encodeURIComponent($('search').value.trim());const status=encodeURIComponent($('statusFilter').value||'active');const d=await api('?action=list&entity=meetings&q='+q+'&status='+status);rows=d.rows||[];meetingSortRows();renderMeetingsList()}catch(e){$('list').innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
function renderMeetingsList(){meetingListPlaceholders();meetingSortRows();const p=meetingPk();$('headerStats').textContent=rows.length+' resultaten · '+(meta.entities.meetings.count||0)+' totaal';$('list').innerHTML=rows.map((x,i)=>'<div class="item '+(selected&&String(selected[p])===String(x[p])?'selected':'')+'" onclick="selectRow('+i+')"><strong>'+esc(meetingTitle(x))+'</strong><span>'+esc(meetingSub(x))+'</span></div>').join('')||'<div class="pad muted">Geen vergaderingen gevonden.</div>';syncListHeader()}
async function selectMeeting(i){try{const x=rows[i];const d=await api('?action=get&entity=meetings&id='+encodeURIComponent(x[meetingPk()]));selected=d.row;currentEntity='meetings';listEntity='meetings';renderMeetingsList();await showMeetingDetail(d.row)}catch(e){$('detail').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
function meetingField(k,v,wide=false){const n=normKey(k);let h='<div class="field'+(wide?' full':'')+'"><label>'+esc(label(k))+'</label>';if(n==='datum'){h+=dateEditor(k,v)}else if(n==='soort'){const opts=(meta.lookups?.meetings?.Soort||[]);h+=selectField(k,v,opts)}else if(n==='actief'){h+='<div class="bool-group"><button type="button" class="bool '+(boolState(v)?'active':'')+'" onclick="setBool(this,true,\'Actief\',\''+esc(boolValue(true,v))+'\')">Waar</button><button type="button" class="bool false '+(!boolState(v)?'active':'')+'" onclick="setBool(this,false,\'Actief\',\''+esc(boolValue(false,v))+'\')">Niet waar</button><input type="hidden" name="Actief" value="'+esc(v||'Waar')+'"></div>'}else if(['agenda','verslag','aanwezig'].includes(n)){h+='<textarea name="'+esc(k)+'" '+(n==='verslag'?'class="meeting-verslag"':'')+'>'+esc(v||'')+'</textarea>'}else{h+='<input name="'+esc(k)+'" value="'+esc(v||'')+'">'}return h+'</div>'}
function meetingForm(r){const x=r||{Datum:'',Soort:'',Locatie:'',Aanwezig:'',Agenda:'',Verslag:'',Actief:'Waar'};return '<form id="meetingForm"><div class="section"><div class="section-head">📅 Vergadering</div><div class="grid">'+meetingField('Datum',x.Datum)+meetingField('Soort',x.Soort)+meetingField('Locatie',x.Locatie)+meetingField('Aanwezig',x.Aanwezig)+meetingField('Agenda',x.Agenda,true)+meetingField('Verslag',x.Verslag,true)+meetingField('Actief',x.Actief)+'</div><div class="actions"><button type="button" class="btn" onclick="cancelEdit()">Annuleren</button>'+(r?'<button type="button" class="btn danger" onclick="deleteRecord(\'meetings\',\''+esc(String(r[meetingPk()]))+'\')">🗑 Deactiveren</button>':'')+'<button type="submit" class="btn primary">💾 Opslaan</button></div></div></form>'}
async function showMeetingDetail(r){currentEntity='meetings';listEntity='meetings';selected=r;$('audit').hidden=false;$('audit').innerHTML=auditHTML('meetings',r);$('detailTitle').textContent=meetingTitle(r);$('detailSub').textContent=meetingSub(r)||('Vergadering #'+r[meetingPk()]);$('detail').innerHTML='<div class="meeting-toolbar"><button class="btn primary" onclick="beginMeetingEdit()">✏️ Wijzigen</button><button class="btn" onclick="openMeetingReport()">📄 Verslag + acties</button><button class="btn" onclick="exportMeetingCsv()">⬇ CSV verslag + acties</button><button class="btn" onclick="sendMeetingReminder()">✉ Herinnering openstaande acties</button></div><div class="section"><div class="section-head">📅 Vergadering</div><div class="view-grid">'+['Datum','Soort','Locatie','Aanwezig','Agenda','Verslag','Actief'].map(k=>'<div class="view-field '+(['Agenda','Verslag'].includes(k)?'full ':'')+'"><label>'+esc(label(k))+'</label><div class="view-value">'+esc(isDateFieldName(k)?dateDisplayValue(r[k]||''):(r[k]||''))+'</div></div>').join('')+'</div></div><div id="meetingActionsSection" class="section"><div class="section-head">✅ Actiepunten</div><div class="pad" id="meetingActionsBody">Laden…</div></div><div id="meetingFilesSection" class="section"><div class="section-head">📎 Bestanden & foto\'s</div><div class="pad" id="meetingFilesBody">Laden…</div></div>';await loadMeetingActions(r[meetingPk()]);await loadMeetingFiles(r[meetingPk()]);}
function beginMeetingEdit(){if(USER_ROLE!=='admin')return;$('audit').hidden=false;$('detail').innerHTML=meetingForm(selected);$('meetingForm').onsubmit=e=>{e.preventDefault();saveMeetingRecord(selected?.[meetingPk()]||null)};autoSizeTextareas($('detail'));const v=$('meetingForm').querySelector('.meeting-verslag');if(v){v.style.minHeight='220px';v.style.height='220px'}}
function newMeetingRecord(){if(USER_ROLE!=='admin')return;currentEntity='meetings';listEntity='meetings';selected=null;$('audit').hidden=true;$('detailTitle').textContent='Nieuwe vergadering';$('detailSub').textContent='Nieuw record';$('detail').innerHTML=meetingForm(null);$('meetingForm').onsubmit=e=>{e.preventDefault();saveMeetingRecord(null)}}
async function saveMeetingRecord(id){const form=$('meetingForm'),o={};for(const el of form.elements)if(el.name)o[el.name]=el.dataset.dateField==='1'?dateInputValue(el.value):el.value;try{const d=await api('?action=save&entity=meetings'+(id!=null?'&id='+encodeURIComponent(id):''),{method:'POST',body:JSON.stringify(o)});meta=await api('?action=meta');const fresh=await api('?action=get&entity=meetings&id='+encodeURIComponent(d.id));selected=fresh.row;currentEntity='meetings';listEntity='meetings';await loadMeetings();await showMeetingDetail(fresh.row);$('detail').insertAdjacentHTML('afterbegin','<div class="okmsg">✓ Vergadering opgeslagen.</div>')}catch(e){$('detail').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
async function loadMeetingActions(mid){try{const d=await api('?action=meeting_actions&entity=meetings&meeting_id='+encodeURIComponent(mid));const rs=d.rows||[];let h='<div class="meeting-toolbar" style="justify-content:flex-end"><button class="btn primary small" onclick="newMeetingAction()">＋ Nieuw actiepunt</button></div>';if(!rs.length)h+='<div class="empty">Geen actiepunten aan deze vergadering gekoppeld.</div>';else{h+='<div style="overflow:auto"><table class="meeting-actions-table"><thead><tr><th>Datum</th><th>Datum gereed</th><th>Actie</th><th>Verantwoordelijk</th><th>Omschrijving</th><th>Gereed</th><th></th></tr></thead><tbody>';rs.forEach(a=>{const id=a[meta.entities.actions.primary];h+='<tr><td>'+esc(dateDisplayValue(first(a,['Datum'])))+'</td><td>'+esc(dateDisplayValue(first(a,['DatumCompleet'])))+'</td><td>'+esc(first(a,['Actie']))+'</td><td>'+esc(first(a,['Verantwoordelijk']))+'</td><td>'+esc(first(a,['Omschrijving']))+'</td><td>'+esc(first(a,['Compleet']))+'</td><td><button class="btn small" type="button" onclick="editMeetingAction(\''+esc(String(id))+ '\')">✏️</button></td></tr>'});h+='</tbody></table></div>'}$('meetingActionsBody').innerHTML=h}catch(e){$('meetingActionsBody').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
function actionEditor(a){a=a||{VergaderingID:selected[meetingPk()],Datum:'',Actie:'',Verantwoordelijk:'',Omschrijving:'',DatumCompleet:'',Compleet:'Niet waar'};const id=a[meta.entities.actions.primary]||'';return '<div class="notice"><form id="actionEditForm"><div class="grid"><div class="field"><label>Datum</label>'+dateEditor('Datum',a.Datum)+'</div><div class="field"><label>Datum gereed</label>'+dateEditor('DatumCompleet',a.DatumCompleet)+'</div><div class="field"><label>Actie</label><input name="Actie" value="'+esc(a.Actie||'')+'"></div><div class="field"><label>Verantwoordelijk</label><input name="Verantwoordelijk" value="'+esc(a.Verantwoordelijk||'')+'"></div><div class="field full"><label>Omschrijving</label><textarea name="Omschrijving" style="min-height:150px">'+esc(a.Omschrijving||'')+'</textarea></div><div class="field"><label>Gereed</label>'+selectField('Compleet',a.Compleet||'Niet waar',['Waar','Niet waar'])+'</div></div><div class="actions"><button type="button" class="btn" onclick="loadMeetingActions(selected[meetingPk()])">Annuleren</button><button type="submit" class="btn primary">💾 Opslaan</button></div></form></div>'}
function newMeetingAction(){$('meetingActionsBody').insertAdjacentHTML('afterbegin',actionEditor());$('actionEditForm').onsubmit=e=>{e.preventDefault();saveMeetingAction(null)}}
async function editMeetingAction(id){try{const d=await api('?action=get&entity=actions&id='+encodeURIComponent(id));const a=d.row;if(!a)throw new Error('Actiepunt niet gevonden.');$('meetingActionsBody').innerHTML=actionEditor(a);$('actionEditForm').onsubmit=e=>{e.preventDefault();saveMeetingAction(id)}}catch(e){$('meetingActionsBody').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
async function saveMeetingAction(id){const f=$('actionEditForm'),o={VergaderingID:selected[meetingPk()]};for(const el of f.elements)if(el.name)o[el.name]=el.dataset.dateField==='1'?dateInputValue(el.value):el.value;try{await api('?action=save&entity=actions'+(id!=null?'&id='+encodeURIComponent(id):''),{method:'POST',body:JSON.stringify(o)});await loadMeetingActions(selected[meetingPk()]);await showMeetingDetail(selected)}catch(e){$('meetingActionsBody').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
async function loadMeetingFiles(mid){try{const d=await api('?action=meeting_documents&entity=meetings&meeting_id='+encodeURIComponent(mid));const ds=d.documents||[];let h=ds.length?ds.map(x=>'<div class="meeting-file-row"><a href="'+esc(x.url||'#')+'" >'+esc(x.Bestandsnaam||'Bestand')+'</a><span class="muted">'+esc(x.Mimetype||'')+'</span></div>').join(''):'<div class="empty">Nog geen bestanden of foto\'s.</div>';if(USER_ROLE==='admin')h+='<div class="asset-upload"><input id="meetingFileInput" type="file" name="documents" multiple><button type="button" class="btn primary" onclick="uploadMeetingFiles()">⬆ Uploaden</button></div>';$('meetingFilesBody').innerHTML=h}catch(e){$('meetingFilesBody').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
async function uploadMeetingFiles(){const input=$('meetingFileInput');if(!input||!input.files.length){if(input)input.click();return}const fd=new FormData();for(const f of input.files)fd.append('documents[]',f);try{await api('?action=upload_meeting_files&entity=meetings&meeting_id='+encodeURIComponent(selected[meetingPk()]),{method:'POST',body:fd});await loadMeetingFiles(selected[meetingPk()])}catch(e){$('meetingFilesBody').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
function meetingReportHtml(){const r=selected;const d=meetingDateDisplay(first(r,['Datum']));return '<div class="meeting-report"><h1>VvE Beheer — Vergaderverslag</h1><div class="report-meta"><strong>'+esc(d)+'</strong> · '+esc(first(r,['Soort']))+' · '+esc(first(r,['Locatie']))+'<br><strong>Aanwezig:</strong> '+esc(first(r,['Aanwezig']))+'</div><div class="section"><div class="section-head">Agenda</div><div class="report-text">'+esc(first(r,['Agenda']))+'</div></div><div class="section"><div class="section-head">Verslag</div><div class="report-text">'+esc(first(r,['Verslag']))+'</div></div><div class="section"><div class="section-head">Actiepunten</div><div id="reportActions">Laden…</div></div></div>'}
async function openMeetingReport(){if(!selected)return;const w=window.open('','_blank','width=1200,height=900');if(!w){alert('Sta pop-ups voor deze pagina toe.');return}let ad=[];try{ad=(await api('?action=meeting_actions&entity=meetings&meeting_id='+encodeURIComponent(selected[meetingPk()]))).rows||[]}catch(e){w.close();alert(e.message);return}const rowsHtml=ad.length?'<table class="meeting-report-table"><thead><tr><th>Datum</th><th>Datum gereed</th><th>Actie</th><th>Verantwoordelijk</th><th>Omschrijving</th><th>Gereed</th></tr></thead><tbody>'+ad.map(a=>'<tr><td>'+esc(dateDisplayValue(first(a,['Datum'])))+'</td><td>'+esc(dateDisplayValue(first(a,['DatumCompleet'])))+'</td><td>'+esc(first(a,['Actie']))+'</td><td>'+esc(first(a,['Verantwoordelijk']))+'</td><td>'+esc(first(a,['Omschrijving']))+'</td><td>'+esc(first(a,['Compleet']))+'</td></tr>').join('')+'</tbody></table>':'<p>Geen actiepunten.</p>';const html=meetingReportHtml().replace('<div id="reportActions">Laden…</div>',rowsHtml);const css='@page{size:A4;margin:15mm}body{font:12px Arial,sans-serif;color:#17202a}h1{font-size:20px;margin:0 0 8px}.report-meta{margin-bottom:14px;color:#536575}.section{border:1px solid #d7e0e8;border-radius:8px;margin:0 0 12px;overflow:hidden}.section-head{background:#eaf4fb;border-bottom:1px solid #d7e0e8;padding:7px 10px;font-weight:700}.report-text{white-space:pre-wrap;line-height:1.45;padding:10px}.meeting-report-table{width:100%;border-collapse:collapse;font-size:10px}.meeting-report-table th,.meeting-report-table td{border:1px solid #cbd3dc;padding:5px;vertical-align:top;text-align:left}.meeting-report-table th{background:#eaf4fb}';w.document.write('<!doctype html><html lang="nl"><head><meta charset="utf-8"><title>Vergaderverslag</title><style>'+css+'</style></head><body>'+html+'</body></html>');w.document.close();w.focus();setTimeout(()=>w.print(),350)}
async function exportMeetingCsv(){if(!selected)return;try{const rs=(await api('?action=meeting_actions&entity=meetings&meeting_id='+encodeURIComponent(selected[meetingPk()]))).rows||[];const m=selected;const lines=[['Vergadering','Datum','Soort','Locatie','Aanwezig','Agenda','Verslag'].map(csvCell).join(';'),[meetingTitle(m),first(m,['Datum']),first(m,['Soort']),first(m,['Locatie']),first(m,['Aanwezig']),first(m,['Agenda']),first(m,['Verslag'])].map(csvCell).join(';'),'',['Actie-ID','Datum','Datum gereed','Actie','Verantwoordelijk','Omschrijving','Gereed'].map(csvCell).join(';')];rs.forEach(a=>lines.push([a[meta.entities.actions.primary],first(a,['Datum']),first(a,['DatumCompleet']),first(a,['Actie']),first(a,['Verantwoordelijk']),first(a,['Omschrijving']),first(a,['Compleet'])].map(csvCell).join(';')));const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='vergaderverslag_'+(dateInputValue(first(m,['Datum']))||new Date().toISOString().slice(0,10))+'_acties.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert(e.message)}}
function ensureMeetingReminderModal(){let modal=$('meetingReminderModal');if(modal)return modal;modal=document.createElement('div');modal.id='meetingReminderModal';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','meetingReminderTitle');modal.style.cssText='display:none;position:fixed;inset:0;z-index:10000;background:rgba(15,23,42,.55);align-items:center;justify-content:center;padding:20px';modal.innerHTML='<div style="width:min(560px,100%);background:#fff;border-radius:16px;box-shadow:0 24px 70px rgba(0,0,0,.28);overflow:hidden"><div id="meetingReminderTitle" style="font-size:20px;font-weight:800;padding:18px 20px;background:#dceefa">Herinnering openstaande acties</div><form id="meetingReminderForm" style="padding:20px"><label for="meetingReminderRecipients" style="display:block;font-weight:700;margin-bottom:8px">E-mailadres(sen)</label><input id="meetingReminderRecipients" type="text" inputmode="email" autocomplete="email" placeholder="bijvoorbeeld naam@example.nl" style="box-sizing:border-box;width:100%;padding:12px;border:1px solid #b8c4d3;border-radius:8px;font:inherit"><div style="color:#64748b;font-size:14px;margin-top:7px">Meerdere adressen mogen met een komma of spatie worden gescheiden.</div><div id="meetingReminderStatus" aria-live="polite" style="display:none;margin-top:14px;padding:11px 12px;border-radius:8px"></div><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:20px"><button id="meetingReminderCancel" type="button" class="btn">Annuleren</button><button id="meetingReminderSubmit" type="submit" class="btn primary">✉ Verzenden</button></div></form></div>';document.body.appendChild(modal);$('meetingReminderCancel').onclick=closeMeetingReminder;modal.addEventListener('click',e=>{if(e.target===modal)closeMeetingReminder()});$('meetingReminderForm').onsubmit=submitMeetingReminder;return modal}
function closeMeetingReminder(){const modal=$('meetingReminderModal');if(modal)modal.style.display='none'}
function sendMeetingReminder(){if(!selected)return;const modal=ensureMeetingReminderModal(),input=$('meetingReminderRecipients'),status=$('meetingReminderStatus'),button=$('meetingReminderSubmit');input.value='';input.disabled=false;button.disabled=false;button.textContent='✉ Verzenden';$('meetingReminderCancel').textContent='Annuleren';status.style.display='none';status.textContent='';modal.style.display='flex';setTimeout(()=>input.focus(),0)}
async function submitMeetingReminder(e){e.preventDefault();const input=$('meetingReminderRecipients'),status=$('meetingReminderStatus'),button=$('meetingReminderSubmit'),to=input.value.trim();status.style.display='block';if(!to){status.style.background='#fff3cd';status.style.color='#7a5200';status.textContent='Vul minimaal één e-mailadres in.';input.focus();return}input.disabled=true;button.disabled=true;button.textContent='Verzenden…';status.style.background='#eef5ff';status.style.color='#234';status.textContent='De herinnering wordt verzonden…';try{const d=await api('?action=send_action_reminder&entity=meetings&meeting_id='+encodeURIComponent(selected[meetingPk()]),{method:'POST',body:JSON.stringify({to})});status.style.background='#e8f7ed';status.style.color='#176b36';status.textContent='✓ Herinnering verzonden naar '+d.sent_to.join(', ')+'. Openstaande acties: '+d.open_actions+'.';button.textContent='Verzonden';$('meetingReminderCancel').textContent='Sluiten'}catch(err){status.style.background='#fdecec';status.style.color='#9f2424';status.textContent=err.message;input.disabled=false;button.disabled=false;button.textContent='Opnieuw proberen';input.focus()}}
async function init(){try{const health=await api('?action=health');$('status').textContent='Verbonden';$('statusMeta').textContent='Database '+(health.database||'')+' · '+health.server_time;meta=await api('?action=meta');$('statusMeta').textContent=meta.entities.contacts.count+' contacten · '+meta.entities.relations.count+' relaties'+(meta.entities.meetings?' · '+meta.entities.meetings.count+' vergaderingen':'')+(meta.entities.Sleutels?' · '+meta.entities.Sleutels.count+' sleutels':'');const params=new URLSearchParams(location.search),entity=params.get('entity'),id=params.get('id'),allowed=['contacts','addresses','relations','Activa','maintenance_plans','meetings'];if(entity&&id&&allowed.includes(entity)&&meta.entities[entity])await openEntity(entity,id,false);else await load()}catch(e){$('status').textContent='Fout';$('statusMeta').textContent='Database/API niet bereikbaar';$('detail').innerHTML='<div class=\"err\"><strong>Verbinding mislukt</strong><br>'+esc(e.message)+'</div>';$('list').innerHTML='<div class=\"pad\"><div class=\"err\">'+esc(e.message)+'</div></div>'}}
async function showListTab(e,b){$('detailTitle').classList.remove('key-detail-title');listEntity=e;currentEntity=null;selected=null;historyStack=[];document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));if(b)b.classList.add('active');$('search').value='';toggleClear('searchbox','search');$('audit').hidden=true;$('detailTitle').textContent='Selecteer een record';$('detailSub').textContent='';$('detail').innerHTML='<div class="notice">Lijst laden…</div>';if(e==='Activa'){ $('listTitle').textContent='Activa'; await loadAssets();return}if(e==='maintenance_plans'){ $('listTitle').textContent='Onderhoudsplannen'; await loadMaintenance();return}if(e==='meetings'){await loadMeetings();return}if(e==='Sleutels'){ $('listTitle').textContent='Sleutels'; await loadKeys(); return}$('listTitle').textContent=e==='contacts'?'Contacten':'Relaties';await load()}
function statusOptionsFor(entity){const raw=meta?.statusOptions?.[entity]||[];return raw.map(x=>typeof x==='string'?{value:x,label:x}:x).filter(x=>x&&x.value!==undefined&&String(x.value)!=='')}
function renderStatusFilter(){const sel=$('statusFilter');if(!sel)return;const opts=statusOptionsFor(listEntity);const current=sel.value||'active';let html='<option value="__all__">Alle statussen</option>';if(opts.length){for(const o of opts)html+='<option value="'+esc(o.value)+'">'+esc(o.label||o.value)+'</option>';}else{html+='<option value="active">Actief</option><option value="inactive">Niet actief</option>';}sel.innerHTML=html;const active=opts.find(o=>String(o.value).toLowerCase()==='actief'||String(o.value).toLowerCase()==='active');if(current==='active'&&active)sel.value=active.value;else if(current==='__all__'||opts.some(o=>String(o.value)===current))sel.value=current;else sel.value=active?active.value:'active'}
async function load(){currentEntity=listEntity;if(listEntity==='meetings'){await loadMeetings();return;}if(listEntity==='Sleutels'){await loadKeys();return;}renderStatusFilter();try{const q=encodeURIComponent($('search').value.trim());const status=encodeURIComponent($('statusFilter')?.value||'active');const d=await api('?action=list&entity='+listEntity+'&q='+q+'&status='+status);rows=d.rows||[];renderList()}catch(e){$('list').innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
function loadDebounced(){toggleClear('searchbox','search');clearTimeout(timer);timer=setTimeout(load,250)}function toggleClear(box,input){$(box).classList.toggle('has-value',!!$(input).value)}function clearSearch(){$('search').value='';toggleClear('searchbox','search');load()}function clearQuestion(){$('question').value='';toggleClear('questionbox','question')}
function updateSortOptions(){const sel=$('sortFilter');if(!sel)return;const current=sel.value||'az';const isContacts=listEntity==='contacts';if(listEntity==='Activa'){sel.innerHTML='<option value="az">A–Z (naam)</option><option value="za">Z–A (naam)</option>';sel.value=['az','za'].includes(current)?current:'az';return}if(listEntity==='maintenance_plans'){sel.innerHTML='<option value="az">A–Z</option><option value="za">Z–A</option><option value="year_desc">Planjaar nieuw → oud</option><option value="year_asc">Planjaar oud → nieuw</option>';sel.value=['az','za','year_desc','year_asc'].includes(current)?current:'az';return}sel.innerHTML=isContacts?'<option value="az">A–Z (achternaam)</option><option value="za">Z–A (achternaam)</option><option value="house_asc">Huisnummer oplopend</option><option value="house_desc">Huisnummer aflopend</option>':'<option value="az">A–Z</option><option value="za">Z–A</option>';sel.value=(isContacts&&['az','za','house_asc','house_desc'].includes(current))||(!isContacts&&['az','za'].includes(current))?current:'az'}function houseNumberParts(row){const raw=String(first(row,['Huisnummer'])||'').trim();const match=raw.match(/^(\d+)\s*(.*)$/);return match?{number:Number(match[1]),suffix:match[2]}:{number:null,suffix:raw}}function sortRows(){const mode=$('sortFilter')?.value||'az';const dir=mode==='za'||mode==='house_desc'||mode==='year_desc'?-1:1;rows.sort((a,b)=>{if(listEntity==='Sleutels')return String(keyTitle(a)||'').localeCompare(String(keyTitle(b)||''),'nl',{sensitivity:'base',numeric:true})*dir;if(listEntity==='maintenance_plans'&&(mode==='year_desc'||mode==='year_asc'))return (Number(first(a,['Planjaar'])||0)-Number(first(b,['Planjaar'])||0))*dir;if(listEntity==='contacts'&&(mode==='house_asc'||mode==='house_desc')){const av=houseNumberParts(a),bv=houseNumberParts(b);if(av.number!==null&&bv.number!==null){const numberCompare=(av.number-bv.number)*dir;if(numberCompare)return numberCompare;const suffixCompare=av.suffix.localeCompare(bv.suffix,'nl',{sensitivity:'base',numeric:true})*dir;if(suffixCompare)return suffixCompare;return name(a).localeCompare(name(b),'nl',{sensitivity:'base',numeric:true})}if(av.number!==null)return -1;if(bv.number!==null)return 1;const rawCompare=av.suffix.localeCompare(bv.suffix,'nl',{sensitivity:'base',numeric:true})*dir;return rawCompare||name(a).localeCompare(name(b),'nl',{sensitivity:'base',numeric:true})}const av=listEntity==='contacts'?first(a,['AchterNaam']):(first(a,['Naam','Alias'])||('Relatie '+a[pk(listEntity)]));const bv=listEntity==='contacts'?first(b,['AchterNaam']):(first(b,['Naam','Alias'])||('Relatie '+b[pk(listEntity)]));return String(av||'').localeCompare(String(bv||''),'nl',{sensitivity:'base',numeric:true})*dir})}function renderList(){if(listEntity==='meetings'){renderMeetingsList();return;}if(listEntity==='Sleutels'){renderKeysList();return;}updateSortOptions();if(currentEntity==='addresses'){ $('listTitle').textContent='Adres'; $('headerStats').textContent='1 resultaat · 1 totaal'; const title=selected?addressTitle(selected,deepContact):'Adres'; const sub=selected?addressSub(selected):''; $('list').innerHTML=selected?`<div class="item selected"><strong>${esc(title)}</strong><span>${esc(sub)}</span></div>`:'<div class="pad muted">Geen adres geselecteerd.</div>';syncListHeader(); return;} const p=pk(listEntity);sortRows();$('listTitle').textContent=listEntity==='contacts'?'Contacten':'Relaties';$('headerStats').textContent=rows.length+' resultaten · '+meta.entities[listEntity].count+' totaal';$('list').innerHTML=rows.map((x,i)=>{let title,sub;if(listEntity==='contacts'){title=name(x);sub='Huisnummer '+first(x,['Huisnummer'])+' · Hal '+first(x,['Hal'])+' · '+first(x,['Status','Actief'])}else{title=first(x,['Naam','Alias'])||('Relatie '+x[p]);sub='Relatie · '+first(x,['Actief'])}return `<div class="item ${selected&&String(selected[p])===String(x[p])?'selected':''}" onclick="selectRow(${i})"><strong>${esc(title)}</strong><span>${esc(sub)}</span></div>`}).join('')||'<div class="pad muted">Geen resultaten.</div>';syncListHeader()}
async function selectRow(i){if(listEntity==='meetings'){await selectMeeting(i);return;}try{const x=rows[i];if(currentEntity&&selected)historyStack.push({entity:currentEntity,row:selected});currentEntity=listEntity;const d=await api('?action=get&entity='+listEntity+'&id='+encodeURIComponent(x[pk(listEntity)]));selected=d.row;await showDetail(listEntity,d.row)}catch(e){$('detail').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
function auditHTML(entity,r){const p=pk(entity),id=r?.[p]??'—';const date=r?.vvegui_modified_at||first(r,['Gewijzigd','gewijzigd','Update','updated_at_source','updated_at','LaatstGewijzigd'])||'—';const by=r?.vvegui_modified_by||first(r,['Gewijzigd door','gewijzigd_door','gewijzigddoor'])||(date!=='—'?'Bronimport':'—');return `<div class="label">Record-ID</div><div class="value">${esc(id)}</div><div class="label">Laatste wijziging</div><div class="value">${esc(date)}</div><div class="label">Door</div><div class="value">${esc(by)}</div>`}
function orderedColumns(entity,cols){const preferred={contacts:['Aanhef','VoorNaam','Voorletters','Tussenvoegsel','AchterNaam','Huisnummer','Hal','Etage','Bergingsgang','Appartementsgrootte','Sinds','VVELid','Bestuurslid','Bewoner','Eigenaar','Huurder','Verhuurder','Derden','Actief','Status','Nieuwsbrief','Jaarverslag','TestAccount','Notities'],addresses:['AdresSoort','NaamSleutelhouder','Straat','Huisnummer','Postcode','Woonplaats','Mobiel','TelefoonHuis','EmailPrive','EmailWerk','Land','Postbus','TelefoonWerk','Fax','Facebook','Twitter','LinkedIn','Website','Notities','Actief','Bewoner: AchterNaam','Hal','Bewoner: VoorNaam','Bewoner: Voorletters','Bewoner: Tussenvoegsel','Bewoner: Toevoegsel','Etage'],relations:['Naam','Alias','CategorieID','SoortID','BTW Nummer','KvKNummer','BankRelatie','IBAN','BIC','SEPAMachtiging','Nieuwsbrief','Actief','Notities']};const used=[];for(const target of (preferred[entity]||[])){const actual=cols.find(c=>normKey(c)===normKey(target));if(actual&&!used.includes(actual))used.push(actual)}for(const k of cols)if(!used.includes(k))used.push(k);return used}

const boolNames=new Set(['VVELid','Bestuurslid','Nieuwsbrief','Jaarverslag','TestAccount','Huurder','Bewoner','Eigenaar','Verhuurder','Derden','Actief','Facebook','Twitter','LinkedIn','WIFI Terminal','Tag Geel','Tag Oranje','Tag Blauw','Tag Rood','Tag Groen','Tag Grijs Rood','SEPAMachtiging']);function isBoolField(k,v){if(['bankrelatie','iban'].includes(normKey(k)))return false;return [...boolNames].some(x=>normKey(x)===normKey(k))||['waar','niet waar','true','false','ja','nee'].includes(String(v??'').trim().toLowerCase())}
function boolState(v){return ['waar','true','1','ja'].includes(String(v??'').trim().toLowerCase())}function boolValue(active,orig){const s=String(orig??'').trim().toLowerCase();if(['true','false'].includes(s))return active?'true':'false';if(['1','0'].includes(s))return active?'1':'0';if(['ja','nee'].includes(s))return active?'Ja':'Nee';return active?'Waar':'Niet waar'}
function isHiddenField(k,entity){const n=normKey(k);const hasIban=(meta?.entities?.relations?.columns||[]).some(c=>normKey(c)==='iban');return n==='legacyjson'||n.startsWith('vvegui')||['update','gewijzigd','gewijzigddoor','updatedatsource','laatstgewijzigd'].includes(n)||isIdField(k)||(entity==='contacts'&&['telefoon','email'].includes(n))||(entity==='relations'&&n==='bankrelatie'&&hasIban)}
function lookupOptions(entity,k){const groups=[meta.lookups?.[entity]||{},meta.lookups?.common||{}];for(const g of groups){const actual=Object.keys(g).find(x=>normKey(x)===normKey(k));if(actual)return g[actual]}return null}
function lookupIdLabelOptions(entity,k){const vals=lookupOptions(entity,k)||[];if(!Array.isArray(vals)){return Object.entries(vals).map(([id,label])=>({value:String(id),label:String(label)}))}return vals.map(x=>{const s=String(x??'');const p=s.split('|');return p.length>1?{value:p.shift().trim(),label:p.join('|').trim()}:{value:s,label:s}}).filter(x=>x.value!==''&&x.label!=='')}
function selectField(k,v,options){return `<select name="${esc(k)}"><option value="">—</option>${options.map(o=>`<option value="${esc(o)}" ${String(o)===String(v??'')?'selected':''}>${esc(o)}</option>`).join('')}</select>`}
function isDateFieldName(k){const n=normKey(k);return n.includes('datum')||n==='date'||n.endsWith('date')||n.includes('geboortedag')||n.includes('sindsdatum')}
function dateInputValue(v){const s=String(v??'').trim();if(!s||/^0000-00-00/.test(s))return '';if(/^\d{4}-\d{2}-\d{2}/.test(s))return s.slice(0,10);const m=s.match(/^(\d{2})[-\/\s](\d{2})[-\/\s](\d{4})$/);return m?m[3]+'-'+m[2]+'-'+m[1]:''}
function dateDisplayValue(v){const iso=dateInputValue(v);if(!iso)return '';const [y,m,d]=iso.split('-');return d+'-'+m+'-'+y}
function dateEditor(k,v){const iso=dateInputValue(v),display=dateDisplayValue(v),id='date_'+Math.random().toString(36).slice(2,9);return '<div class="date-editor"><input class="date-text" id="'+id+'_text" name="'+esc(k)+'" data-date-field="1" inputmode="numeric" autocomplete="off" placeholder="DD-MM-JJJJ" value="'+esc(display)+'" maxlength="10" onblur="normalizeDateText(this)" oninput="syncDateTextToPicker(this,\''+id+'\')"><input class="date-picker" id="'+id+'_picker" type="date" value="'+esc(iso)+'" aria-label="Kies datum" onchange="syncPickerToDateText(this,\''+id+'\')"><button type="button" class="date-picker-btn" title="Kies datum" onclick="const p=document.getElementById(\''+id+'_picker\');p.showPicker?p.showPicker():p.click()">📅</button></div>'}
function normalizeDateText(el){const v=String(el.value||'').trim();if(!v){el.value='';return}const m=v.match(/^(\d{2})[-\/\s](\d{2})[-\/\s](\d{4})$/);if(m)el.value=m[1]+'-'+m[2]+'-'+m[3];else if(/^\d{4}[-\/]\d{2}[-\/]\d{2}$/.test(v)){const a=v.split(/[-\/]/);el.value=a[2]+'-'+a[1]+'-'+a[0]}}
function syncPickerToDateText(picker,id){const t=document.getElementById(id+'_text');if(t)t.value=picker.value?dateDisplayValue(picker.value):''}
function syncDateTextToPicker(text,id){const p=document.getElementById(id+'_picker');if(p){const iso=dateInputValue(text.value);if(iso)p.value=iso}}
function fieldEdit(k,v){const comment=normKey(k)==='notities'||normKey(k)==='opmerkingen';const area=comment||String(v??'').length>120;const options=lookupOptions(currentEntity,k);if(options)return `<div class="field"><label>${esc(label(k))}</label>${selectField(k,v,options)}</div>`;if(isDateFieldName(k))return `<div class="field"><label>${esc(label(k))}</label>${dateEditor(k,v)}</div>`;if(isBoolField(k,v))return `<div class="field"><label>${esc(label(k))}</label><div class="bool-group"><button type="button" class="bool ${boolState(v)?'active':''}" onclick="setBool(this,true,'${esc(k)}','${esc(boolValue(true,v))}')">Waar</button><button type="button" class="bool false ${!boolState(v)?'active':''}" onclick="setBool(this,false,'${esc(k)}','${esc(boolValue(false,v))}')">Niet waar</button><input type="hidden" name="${esc(k)}" value="${esc(v??'')}"></div></div>`;return `<div class="field ${area?'full':''}${comment?' comments-field':''}"><label>${esc(label(k))}</label>${area?`<textarea name="${esc(k)}">${esc(v??'')}</textarea>`:`<input name="${esc(k)}" value="${esc(v??'')}">`}</div>`}
function renderView(entity,r){const cols=orderedColumns(entity,meta.entities[entity].columns).filter(k=>!isHiddenField(k,entity));const body=cols.map(k=>{const raw=r?.[k]??'';const shown=isDateFieldName(k)?dateDisplayValue(raw):raw;return '<div class="view-field '+(String(raw).length>120?'full ':'')+(normKey(k)==='notities'||normKey(k)==='opmerkingen'?' comments-field':'')+'"><label>'+esc(label(k))+'</label><div class="view-value">'+esc(shown)+'</div></div>'}).join('');return '<div class="section"><div class="section-head">📋 Gegevens</div><div class="view-grid">'+body+'</div></div>'+(USER_ROLE==='admin'?'<div class="actions"><button class="btn primary" onclick="beginEdit()">✏️ Wijzigen</button></div>':'')}
function keyAssetOptions(v){
  const ar=Array.isArray(assetRows)&&assetRows.length?assetRows:[];
  return '<select name="ActivaID"><option value="">— Geen activum —</option>'+ar.filter(a=>boolState(first(a,['Actief']))||String(first(a,['Actief'])).trim()==='' ).map(a=>{const id=a[pk('Activa')];return '<option value="'+esc(String(id))+'" '+(String(id)===String(v??'')?'selected':'')+'>'+esc(assetName(a))+'</option>'}).join('')+'</select>';
}
function keyFieldEdit(k,v,row,isNew=false){
  const n=normKey(k);
  if(n==='activaid') return '<div class="field"><label>Activum</label>'+keyAssetOptions(v)+'</div>';
  if(n==='uitleendatum'||n==='retourdatum') return '<div class="field"><label>'+esc(label(k))+'</label>'+dateEditor(k,v)+'</div>';
  if(n==='actief') return '<div class="field"><label>Actief</label><div class="bool-group"><button type="button" class="bool '+(boolState(v)||v===''?'active':'')+'" onclick="setBool(this,true,\''+esc(k)+'\',\'Waar\')">Waar</button><button type="button" class="bool false '+(!boolState(v)&&v!==''?'active':'')+'" onclick="setBool(this,false,\''+esc(k)+'\',\'Niet waar\')">Niet waar</button><input type="hidden" name="'+esc(k)+'" value="'+esc(v||'Waar')+'"></div></div>';
  const area=n==='omschrijving';
  const cls=area?'key-description-field':(n==='locatie'?'key-location-field':'');
  return '<div class="field '+cls+'"><label>'+esc(label(k))+'</label>'+(area?'<textarea name="'+esc(k)+'" rows="2">'+esc(v??'')+'</textarea>':'<input name="'+esc(k)+'" value="'+esc(v??'')+'">')+'</div>';
}
function keyColumns(){return ['Functie','ActivaID','Omschrijving','Verantwoordelijk','Merk','Sleutelnummer','Locatie','UitgeleendAan','Uitleendatum','Retourdatum','Actief'];}
function keyForm(row){const isNew=!row;const x=row||{Functie:'',Omschrijving:'',Verantwoordelijk:'',Merk:'',Sleutelnummer:'',Locatie:'Sleutelkastje in de hydrofoor ruimte',ActivaID:'',UitgeleendAan:'',Uitleendatum:'',Retourdatum:'',Actief:'Waar'};return '<form id="editForm"><div class="section"><div class="section-head">🔑 Sleutel</div><div class="grid"><div class="key-primary-row">'+keyFieldEdit('Functie',x.Functie,row,isNew)+keyFieldEdit('ActivaID',x.ActivaID,row,isNew)+'</div>'+keyFieldEdit('Omschrijving',x.Omschrijving,row,isNew)+keyFieldEdit('Verantwoordelijk',x.Verantwoordelijk,row,isNew)+keyFieldEdit('Merk',x.Merk,row,isNew)+keyFieldEdit('Sleutelnummer',x.Sleutelnummer,row,isNew)+keyFieldEdit('Locatie',x.Locatie,row,isNew)+keyFieldEdit('UitgeleendAan',x.UitgeleendAan,row,isNew)+keyFieldEdit('Uitleendatum',x.Uitleendatum,row,isNew)+keyFieldEdit('Retourdatum',x.Retourdatum,row,isNew)+keyFieldEdit('Actief',x.Actief,row,isNew)+'</div><div class="actions"><button type="button" class="btn" onclick="cancelEdit()">Annuleren</button>'+(row?'<button type="button" class="btn danger" onclick="deleteRecord(\'Sleutels\',\''+esc(String(row[pk('Sleutels')]))+'\')">🗑 Deactiveren</button>':'')+'<button type="submit" class="btn primary">💾 Opslaan</button></div></div></form>'}
function keyStatus(r){const u=String(first(r,['UitgeleendAan'])||'').trim(),ret=String(first(r,['Retourdatum'])||'').trim();return u&&!ret?'Uitgeleend':'Beschikbaar'}
function keyTitle(r){const f=String(first(r,['Functie'])||'').trim();const a=first(r,['ActivaID'])?keyAssetName(first(r,['ActivaID'])):'';return [f,a].filter(Boolean).join(' ')||('Sleutel '+String(first(r,['Sleutelnummer'])||r[pk('Sleutels')]||''))}
function keySub(r){return keyStatus(r)}
function renderKeysList(){updateSortOptions();$('listTitle').textContent='Sleutels';$('headerStats').textContent=rows.length+' resultaten · '+(meta.entities.Sleutels?.count||0)+' totaal';$('list').innerHTML=rows.map((x,i)=>'<div class="item '+(selected&&String(selected[pk('Sleutels')])===String(x[pk('Sleutels')])?'selected':'')+'" onclick="selectRow('+i+')"><strong class="key-item-title">'+esc(keyTitle(x))+'</strong><span>'+esc(keySub(x))+'</span></div>').join('')||'<div class="pad muted">Geen sleutels gevonden.</div>';syncListHeader()}
async function loadKeys(){currentEntity='Sleutels';renderStatusFilter();try{if(!assetRows||!assetRows.length)await loadAssets();const q=encodeURIComponent($('search').value.trim());const status=encodeURIComponent($('statusFilter')?.value||'__all__');const d=await api('?action=list&entity=Sleutels&q='+q+'&status='+status);rows=d.rows||[];renderKeysList()}catch(e){$('list').innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
function keyAssetName(id){const a=(assetRows||[]).find(x=>String(x[pk('Activa')])===String(id));return a?assetName(a):('Activum #'+id)}
function openKeyRelated(el){if(!el?.dataset?.id)return;openEntity('Sleutels',el.dataset.id,true)}
function keyViewField(k,r){let v=r?.[k]??'';const n=normKey(k);if(n==='activaid'&&v)v=keyAssetName(v);if(isDateFieldName(k))v=dateDisplayValue(v);return '<div class="view-field"><label>'+esc(n==='activaid'?'Activum':label(k))+'</label><div class="view-value">'+esc(v||'—')+'</div></div>'}
function showKeyDetail(r){currentEntity='Sleutels';selected=r;$('audit').hidden=false;$('audit').innerHTML=auditHTML('Sleutels',r);$('detailTitle').textContent=keyTitle(r);$('detailTitle').classList.add('key-detail-title');$('detailSub').textContent=keySub(r);const cols=keyColumns();let h='<div class="section"><div class="section-head">📋 Gegevens</div><div class="view-grid"><div class="key-primary-view-row">'+keyViewField('Functie',r)+keyViewField('ActivaID',r)+'</div>'+keyViewField('Omschrijving',r).replace('class="view-field"','class="view-field full"')+cols.filter(k=>!['Functie','ActivaID','Omschrijving'].includes(k)).map(k=>keyViewField(k,r)).join('')+'</div></div>'+(USER_ROLE==='admin'?'<div class="actions"><button class="btn primary" onclick="beginEdit()">✏️ Wijzigen</button></div>':'');$('detail').innerHTML=h}
async function beginKeyEdit(){if(USER_ROLE!=='admin')return;assetRows=assetRows||[];if(!assetRows.length)await loadAssets();$('detail').innerHTML=keyForm(selected);$('editForm').onsubmit=e=>{e.preventDefault();saveRecord('Sleutels',selected?.[pk('Sleutels')]??null)};autoSizeTextareas($('detail'))}
async function newKeyRecord(){if(USER_ROLE!=='admin')return;currentEntity='Sleutels';listEntity='Sleutels';selected=null;$('audit').hidden=true;$('detailTitle').classList.add('key-detail-title');$('detailTitle').textContent='Nieuwe sleutel';$('detailSub').textContent='Nieuw record';assetRows=assetRows||[];if(!assetRows.length)await loadAssets();$('detail').innerHTML=keyForm(null);$('editForm').onsubmit=e=>{e.preventDefault();saveRecord('Sleutels',null)}}

function formFor(entity,row){const p=pk(entity),req=meta.required?.[entity]||[],base=row||(()=>{const d={};const ak=(meta.entities?.[entity]?.columns||[]).find(k=>normKey(k)==='actief');if(ak)d[ak]='Waar';return d})();const cols=orderedColumns(entity,meta.entities[entity].columns).filter(k=>!isHiddenField(k,entity));const del=row&&row[p]!=null&&USER_ROLE==='admin'?'<button type="button" class="btn danger" onclick="deleteRecord(\''+entity+'\',\''+esc(String(row[p]))+'\')">🗑 Deactiveren</button>':'';return '<form id="editForm" data-required="'+esc(req.join('|'))+'"><div class="grid">'+cols.map(k=>fieldEdit(k,base?.[k]??'')).join('')+'</div><div class="actions"><button type="button" class="btn" onclick="cancelEdit()">Annuleren</button>'+del+'<button type="submit" class="btn primary">💾 Opslaan</button></div></form>'}
function autoSizeTextareas(root=document){root.querySelectorAll('textarea.comments-field, .comments-field textarea').forEach(t=>{t.style.height='auto';const max=360;const h=Math.min(Math.max(t.scrollHeight,68),max);t.style.height=h+'px';t.style.overflowY=t.scrollHeight>max?'auto':'hidden'});}document.addEventListener('input',e=>{if(e.target&&e.target.matches('.comments-field textarea'))autoSizeTextareas(e.target.form||document)});
function setBool(btn,active,key,value){const g=btn.parentElement;g.querySelectorAll('.bool').forEach(b=>b.classList.remove('active'));btn.classList.add('active');g.querySelector('input[type=hidden]').value=value}
function addressOwnerName(a,c=null,r=null){if(c)return name(c);if(r)return first(r,['Naam','Alias'])||('Relatie '+r[pk('relations')]);return first(a,['NaamSleutelhouder'])||addressContactName(a)||'Adres'}function addressTitle(a,c=null,r=null){return addressOwnerName(a,c,r)}function addressSub(a){const soort=first(a,['AdresSoort','adres_soort']);const sleutelhouder=first(a,['NaamSleutelhouder']);const parts=[[soort,[first(a,['Straat','straat']),first(a,['Huisnummer','huisnummer'])].filter(Boolean).join(' ')].filter(Boolean).join(' · '),[first(a,['Postcode','postcode']),first(a,['Woonplaats','woonplaats'])].filter(Boolean).join(' '),first(a,['Mobiel','mobiel']),first(a,['EmailPrive','email_prive'])].filter(Boolean);if(normKey(soort)==='sleuteladres'&&sleutelhouder)parts.splice(1,0,'Naam sleutelhouder: '+sleutelhouder);return parts.join(' · ')}
async function showDetail(entity,r){if(entity==='meetings'){await showMeetingDetail(r);return;}if(entity==='Sleutels'){showKeyDetail(r);return;}currentEntity=entity;selected=r;$('audit').hidden=false;$('audit').innerHTML=auditHTML(entity,r);let title,sub;if(entity==='contacts'){title=name(r);sub='Contactrecord'}else if(entity==='relations'){title=first(r,['Naam','Alias'])||('Relatie '+r[pk(entity)]);sub='Relatierecord'}else{let d=await api('?action=related&entity=addresses&id='+encodeURIComponent(r[pk(entity)]));const c=d.related.contacts?.[0];title=addressTitle(r,c);sub='Adresrecord';} $('detailTitle').textContent=title;$('detailSub').textContent=sub;$('detail').innerHTML=renderView(entity,r)+'<div id="related" class="related"><div class="related-head">🔗 Gekoppelde gegevens</div><div class="empty">Gegevens laden…</div></div>';try{const d=await api('?action=related&entity='+entity+'&id='+encodeURIComponent(r[pk(entity)]));renderRelated(entity,d.related)}catch(e){$('related').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
function card(entity,r,title,sub){const id=r[pk(entity)];return `<div class="rel-card"><strong>${esc(title)}</strong><span>${esc(sub||'')}</span><button class="btn small" onclick="openEntity('${entity}','${esc(String(id))}',true)">Openen</button></div>`}
function renderRelated(entity,x){let html='';if(entity==='contacts'){
const addressCards=x.addresses.length?x.addresses.map(a=>{const c=selected;return card('addresses',a,addressTitle(a,c),addressSub(a))}).join(''):'<div class="empty">Geen gekoppeld adres gevonden.</div>';html+='<div class="related-head">🏠 Adressen & contactgegevens</div><div class="related-grid">'+addressCards+'</div>'+(USER_ROLE==='admin'?'<div class="actions"><button class="btn primary small" onclick="newRelatedRecord(\'addresses\')">＋ Nieuw adres</button></div>':'');
html+='<div class="related-head">🔗 Relaties</div><div class="related-grid">'+(x.relations.length?x.relations.map(r=>card('relations',r,first(r,['Naam','Alias'])||('Relatie '+r[pk('relations')]),'')).join(''):'<div class="empty">Geen gekoppelde relatie gevonden.</div>')+'</div>';

}else if(entity==='relations'){html+='<div class="related-head">👤 Contacten</div><div class="related-grid">'+(x.contacts.length?x.contacts.map(c=>card('contacts',c,name(c),'Huisnummer '+first(c,['Huisnummer'])+' · Hal '+first(c,['Hal']))).join(''):'<div class="empty">Geen gekoppeld contact gevonden.<br><button class="btn primary small" onclick="newRelatedRecord(\'contacts\')">＋ Nieuw contact</button></div>')+'</div><div class="related-head">🏠 Adressen</div><div class="related-grid">'+(x.addresses.length?x.addresses.map(a=>card('addresses',a,addressTitle(a,null,selected),addressSub(a))).join(''):'<div class="empty">Geen gekoppeld adres gevonden.<br><button class="btn primary small" onclick="newRelatedRecord(\'addresses\')">＋ Nieuw adres</button></div>')+'</div>'}else{html+=x.contacts.length?'<div class="related-head">👤 '+esc(name(x.contacts[0]))+'</div><div class="related-grid">'+x.contacts.map(c=>card('contacts',c,name(c),'Huisnummer '+first(c,['Huisnummer'])+' · Hal '+first(c,['Hal']))).join('')+'</div>':'<div class="related-head">👤 Geen gekoppeld contact</div><div class="related-grid"><div class="empty">Geen gekoppeld contact gevonden.<br><button class="btn primary small" onclick="newRelatedRecord(\'contacts\')">＋ Nieuw contact</button></div></div>';html+='<div class="related-head">🔗 Relatie</div><div class="related-grid">'+(x.relations.length?x.relations.map(r=>card('relations',r,first(r,['Naam','Alias'])||('Relatie '+r[pk('relations')]),'')).join(''):'<div class="empty">Geen gekoppelde relatie gevonden.</div>')+'</div>'}$('related').innerHTML=html}
function renderRelated(entity,x){let html='';if(entity==='contacts'){const addressCards=x.addresses.length?x.addresses.map(a=>card('addresses',a,addressTitle(a,selected),addressSub(a))).join(''):'<div class="empty">Geen gekoppeld adres gevonden.</div>';html+='<div class="related-head">🏠 Adressen & contactgegevens</div><div class="related-grid">'+addressCards+'</div>'+(USER_ROLE==='admin'?'<div class="actions"><button class="btn primary small" onclick="newRelatedRecord(\'addresses\')">＋ Nieuw adres</button></div>':'');html+='<div class="related-head">🔗 Relaties</div><div class="related-grid">'+(x.relations.length?x.relations.map(r=>card('relations',r,first(r,['Naam','Alias'])||('Relatie '+r[pk('relations')]),'')).join(''):'<div class="empty">Geen gekoppelde relatie gevonden.</div>')+'</div>'}else if(entity==='relations'){html+='<div class="related-head">👤 Contacten</div><div class="related-grid">'+(x.contacts.length?x.contacts.map(c=>card('contacts',c,name(c),'Huisnummer '+first(c,['Huisnummer'])+' · Hal '+first(c,['Hal']))).join(''):'<div class="empty">Geen gekoppeld contact gevonden.</div>')+'</div>'+(USER_ROLE==='admin'?'<div class="actions"><button class="btn primary small" onclick="chooseRelationContacts()">＋ Bestaande contacten koppelen</button></div>':'')+'<div class="related-head">🏠 Adressen</div><div class="related-grid">'+(x.addresses.length?x.addresses.map(a=>card('addresses',a,addressTitle(a,null,selected),addressSub(a))).join(''):'<div class="empty">Geen gekoppeld adres gevonden.</div>')+'</div>'}else{html+=x.contacts.length?'<div class="related-head">👤 '+esc(name(x.contacts[0]))+'</div><div class="related-grid">'+x.contacts.map(c=>card('contacts',c,name(c),'Huisnummer '+first(c,['Huisnummer'])+' · Hal '+first(c,['Hal']))).join('')+'</div>':'<div class="related-head">👤 Geen gekoppeld contact</div><div class="related-grid"><div class="empty">Geen gekoppeld contact gevonden.</div></div>';html+='<div class="related-head">🔗 Relatie</div><div class="related-grid">'+(x.relations.length?x.relations.map(r=>card('relations',r,first(r,['Naam','Alias'])||('Relatie '+r[pk('relations')]),'')).join(''):'<div class="empty">Geen gekoppelde relatie gevonden.</div>')+'</div>'}$('related').innerHTML=html}
async function chooseRelationContacts(){if(USER_ROLE!=='admin'||currentEntity!=='relations'||!selected)return;const relationId=String(selected[pk('relations')]);try{const [all,current]=await Promise.all([api('?action=list&entity=contacts&status=__all__&q='),api('?action=related&entity=relations&id='+encodeURIComponent(relationId))]);const linked=new Set((current.related.contacts||[]).map(c=>String(c[pk('contacts')]||'')));const contacts=(all.rows||[]).filter(c=>String(c[pk('contacts')]??'')!=='').sort((a,b)=>name(a).localeCompare(name(b),'nl'));$('related').innerHTML='<div class="related-head">👤 Bestaande contacten koppelen</div><div class="pad"><p class="muted">Alle contacten worden getoond, inclusief externe en niet-actieve contacten. Zoek op naam, adres, e-mail, telefoon of status.</p><div class="searchbox"><input id="relationContactSearch" placeholder="Zoek een contact…" oninput="filterRelationContacts(this.value)"><button class="clearx" type="button" aria-label="Wis zoekveld" onclick="this.previousElementSibling.value=\'\';filterRelationContacts(\'\');this.previousElementSibling.focus()">×</button></div><select id="relationContactPicker" multiple size="14" style="width:100%;min-height:21rem;margin-top:10px">'+contacts.map(c=>{const id=String(c[pk('contacts')]);const details=[first(c,['Huisnummer']),first(c,['EmailPrive','EmailWerk']),first(c,['Mobiel','TelefoonHuis','TelefoonWerk']),first(c,['Status','Actief']),boolState(first(c,['Derden']))?'Extern':''].filter(Boolean).join(' · ');const search=Object.values(c).join(' ').toLowerCase();return '<option value="'+esc(id)+'" data-search="'+esc(search)+'"'+(linked.has(id)?' selected':'')+'>'+esc(name(c)+(details?' — '+details:''))+'</option>'}).join('')+'</select><div id="relationContactCount" class="muted">'+contacts.length+' contacten getoond.</div><div class="actions"><button class="btn" onclick="showDetail(\'relations\',selected)">Annuleren</button><button class="btn primary" onclick="saveRelationContacts()">💾 Koppelingen opslaan</button></div></div>'}catch(e){$('related').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
function filterRelationContacts(value){const q=String(value||'').trim().toLowerCase();const picker=$('relationContactPicker');if(!picker)return;let shown=0;for(const option of picker.options){const match=!q||String(option.dataset.search||option.textContent).includes(q);option.hidden=!match;if(match)shown++}const counter=$('relationContactCount');if(counter)counter.textContent=shown+' contacten getoond.'}
async function saveRelationContacts(){const relationId=String(selected?.[pk('relations')]??'');const picker=$('relationContactPicker');if(!relationId||!picker)return;const contactIds=Array.from(picker.selectedOptions).map(o=>o.value);try{await api('?action=set_relation_contacts&entity=relations&relation_id='+encodeURIComponent(relationId),{method:'POST',body:JSON.stringify({contact_ids:contactIds})});await showDetail('relations',selected);$('detail').insertAdjacentHTML('afterbegin','<div class="okmsg">✓ Contactkoppelingen opgeslagen.</div>')}catch(e){$('related').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
async function openEntity(entity,id,deep=false){if(deep&&currentEntity&&selected)historyStack.push({entity:currentEntity,row:selected,listEntity,deepContact,deepRelation});else historyStack=[];const d=await api('?action=get&entity='+entity+'&id='+encodeURIComponent(id));selected=d.row;currentEntity=entity;const navIndex=['contacts','relations','Activa','maintenance_plans','meetings','Sleutels'].indexOf(entity);if(navIndex>=0)document.querySelectorAll('nav button').forEach((b,i)=>b.classList.toggle('active',i===navIndex));if(entity!=='addresses'){listEntity=entity;deepContact=null;deepRelation=null;if(deep){$('search').value='';toggleClear('searchbox','search');await load();}else{renderList();}}else{const rd=await api('?action=related&entity=addresses&id='+encodeURIComponent(id));deepContact=rd.related.contacts?.[0]||null;deepRelation=rd.related.relations?.[0]||null;rows=[d.row];$('search').value='';toggleClear('searchbox','search');renderList();}await showDetail(entity,d.row)}
function beginEdit(){if(currentEntity==='meetings'){beginMeetingEdit();return;}if(currentEntity==='Sleutels'){beginKeyEdit();return;}if(USER_ROLE!=='admin')return;$('detail').innerHTML=formFor(currentEntity,selected);autoSizeTextareas($('detail'));$('editForm').onsubmit=e=>{e.preventDefault();saveRecord(currentEntity,selected?.[pk(currentEntity)])}}
function cancelEdit(){if(currentEntity==='meetings'){if(selected)showMeetingDetail(selected);return;}if(selected)showDetail(currentEntity,selected);}
function goBack(){if(historyStack.length===0)return;const h=historyStack.pop();currentEntity=h.entity;listEntity=h.listEntity||h.entity;selected=h.row;deepContact=h.deepContact||null;deepRelation=h.deepRelation||null;document.querySelectorAll('nav button').forEach((b,i)=>b.classList.toggle('active',listEntity===['contacts','relations','Activa','maintenance_plans','meetings','Sleutels'][i]));if(currentEntity!=='addresses'){load()}else{renderList();showDetail(currentEntity,selected)}}
function newRecord(){if(listEntity==='meetings'){newMeetingRecord();return}if(listEntity==='Sleutels'){newKeyRecord();return}if(USER_ROLE!=='admin')return;currentEntity=listEntity;selected=null;pendingParent=null;historyStack=[];$('audit').hidden=true;$('detailTitle').textContent='Nieuw '+(listEntity==='contacts'?'contact':'relatie');$('detailSub').textContent='Nieuw record';$('detail').innerHTML=formFor(listEntity,null);autoSizeTextareas($('detail'));$('editForm').onsubmit=e=>{e.preventDefault();saveRecord(listEntity,null)}}
function newRelatedRecord(entity){if(USER_ROLE!=='admin'||!selected)return;let contactId='',relationId='',parentLabel='';if(currentEntity==='contacts'){contactId=String(selected[pk('contacts')]);parentLabel=name(selected)}else if(currentEntity==='relations'){relationId=String(selected[pk('relations')]);parentLabel=first(selected,['Naam','Alias'])||('Relatie '+relationId)}else{return}pendingParent={contactId,relationId};historyStack.push({entity:currentEntity,row:selected,listEntity,deepContact,deepRelation});currentEntity=entity;const title=entity==='addresses'?'Nieuw adres':'Nieuwe relatie';$('audit').hidden=true;$('detailTitle').textContent=title;$('detailSub').textContent='Gekoppeld aan '+parentLabel;$('detail').innerHTML=formFor(entity,null);autoSizeTextareas($('detail'));$('editForm').onsubmit=e=>{e.preventDefault();saveRecord(entity,null)}}
async function saveRecord(entity,id){if(entity==='meetings'){await saveMeetingRecord(id);return;}const form=$('editForm'),required=(form.dataset.required||'').split('|').filter(Boolean),missing=[];for(const k of required){const el=form.elements[k];if(el&&!String(el.value||'').trim()){el.classList.add('required-warning');missing.push(label(k))}}if(missing.length){$('detail').insertAdjacentHTML('afterbegin','<div class="warn">⚠️ Verplichte velden ontbreken: '+esc(missing.join(', '))+'</div>');return}const o={};for(const el of form.elements)if(el.name)o[el.name]=el.dataset.dateField==='1'?dateInputValue(el.value):el.value;try{let path='?action=save&entity='+entity+(id!=null?'&id='+encodeURIComponent(id):'');if(id==null&&pendingParent){if(pendingParent.contactId)path+='&parent_contact_id='+encodeURIComponent(pendingParent.contactId);if(pendingParent.relationId)path+='&parent_relation_id='+encodeURIComponent(pendingParent.relationId)}const d=await api(path,{method:'POST',body:JSON.stringify(o)});meta=await api('?action=meta');pendingParent=null;listEntity=entity;await load();const fresh=await api('?action=get&entity='+entity+'&id='+encodeURIComponent(d.id));selected=fresh.row;currentEntity=entity;await showDetail(entity,fresh.row);const msg='✓ Mutatie opgeslagen door '+esc(meta.user.name)+'.';$('detail').insertAdjacentHTML('afterbegin','<div class="okmsg">'+msg+'</div>')}catch(e){$('detail').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
async function deleteRecord(entity,id){if(USER_ROLE!=='admin'||!confirm('Dit record op Niet actief zetten? Het record en gekoppelde child-records blijven behouden.'))return;try{await api('?action=delete&entity='+entity+'&id='+encodeURIComponent(id),{method:'POST'});selected=null;historyStack=[];await load();cancelEdit()}catch(e){alert(e.message)}}
function questionTokens(q){const stop=new Set(['wie','wat','waar','welke','welk','waarom','hoe','is','zijn','de','het','een','van','voor','op','in','aan','met','heeft','hebben','woont','wonen','staat','zit','bevindt','ligt','kan','kun','ik','je','mij','me','contact','contactpersoon','persoon','eigenaar','bewoner','adres','huisnummer','nummer','appartement','telefoonnummer','telefoon','mobiel','email','e-mailadres','eigenaren','bewoners','gegevens']);return String(q).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9@+._ -]/g,' ').split(/\s+/).filter(x=>x&&!stop.has(x)&&x.length>1)}
function rowMatchesQuestion(r,tokens){if(!tokens.length)return true;const vals=Object.values(r||{}).map(v=>String(v??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9@+._ -]/g,''));return tokens.every(tok=>{const n=tok.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9@+._ -]/g,'');return vals.some(v=>v.includes(n))})}
async function answerQuestion(){const q=$('question').value.trim();if(!q)return;const m=q.match(/(?:nummer|huisnummer|appartement)\s*(?:nr\.?\s*)?(\d+)/i);const lower=q.toLowerCase();const looksAsset=/(waar\s+(zit|staat|bevindt)|locatie|activum|activa|installatie|lift|machinekamer|besturing|gebouw|technische ruimte)/i.test(lower);if(m){listEntity='contacts';document.querySelectorAll('nav button').forEach((x,i)=>x.classList.toggle('active',i===0));$('search').value=m[1];toggleClear('searchbox','search');await load();return}if(looksAsset){listEntity='Activa';currentEntity='Activa';document.querySelectorAll('nav button').forEach((x,i)=>x.classList.toggle('active',i===2));const qn=q.replace(/\b(waar|zit|staat|bevindt|de|het|een|van|voor|op|in|is|ligt)\b/gi,' ').replace(/\s+/g,' ').trim();$('search').value=qn;toggleClear('searchbox','search');await load();const firstMatch=assetRows.find(a=>assetMatches(a,qn));if(firstMatch)await selectAsset(firstMatch[pk('Activa')]);return}const tokens=questionTokens(q);for(const [entity,navIndex] of [['contacts',0],['relations',1],['Activa',2]]){try{const d=await api('?action=list&entity='+entity+'&status=__all__&q=');const matches=(d.rows||[]).filter(r=>rowMatchesQuestion(r,tokens));if(matches.length){listEntity=entity;currentEntity=entity;document.querySelectorAll('nav button').forEach((x,i)=>x.classList.toggle('active',i===navIndex));if(entity==='Activa'){$('search').value=tokens.join(' ');toggleClear('searchbox','search');await load();const hit=assetRows.find(a=>String(a[pk('Activa')])===String(matches[0][pk('Activa')]));if(hit)await selectAsset(hit[pk('Activa')]);}else{rows=matches;$('search').value=tokens.join(' ');toggleClear('searchbox','search');renderList()}return}}catch(e){}}listEntity='contacts';document.querySelectorAll('nav button').forEach((x,i)=>x.classList.toggle('active',i===0));$('search').value=q;toggleClear('searchbox','search');await load()} /* === Activa module: geïntegreerd in dezelfde index.php === */
let assetRows=[],assetCategories=[],assetExpanded=new Set();
function isAssets(){return listEntity==='Activa'||currentEntity==='Activa'}
function assetName(a){return String(first(a,['Naam','Alias'])||('Activum '+a[pk('Activa')]))}
function assetChildren(id){const out=assetRows.filter(x=>String(first(x,['ParentActivaID']))===String(id));const dir=($('sortFilter')?.value==='za')?-1:1;return out.sort((a,b)=>String(assetName(a)||'').localeCompare(String(assetName(b)||''),'nl',{sensitivity:'base',numeric:true})*dir)}
function assetRoots(){const out=assetRows.filter(x=>{const p=first(x,['ParentActivaID']);return p===''||p===null||p===undefined||!assetRows.some(y=>String(y[pk('Activa')])===String(p))});const dir=($('sortFilter')?.value==='za')?-1:1;return out.sort((a,b)=>String(assetName(a)||'').localeCompare(String(assetName(b)||''),'nl',{sensitivity:'base',numeric:true})*dir)}
function assetMatches(a,q){if(!q)return true;const n=x=>String(x??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'');const fields=[assetName(a),first(a,['Functie','Omschrijving','ActivaID']),...Object.values(a||{})].map(n);const tokens=String(q).trim().split(/\s+/).map(n).filter(Boolean);return tokens.every(tok=>fields.some(v=>v.includes(tok)))}function assetVisibleSet(q){if(!q)return null;const keep=new Set();for(const a of assetRows){if(assetMatches(a,q)){let cur=a;while(cur){const id=String(cur[pk('Activa')]);if(keep.has(id))break;keep.add(id);const parent=first(cur,['ParentActivaID']);cur=assetRows.find(x=>String(x[pk('Activa')])===String(parent))||null;}}}return keep}
function renderAssetTree(){const box=$('list');const q=String($('search').value||'').trim().toLowerCase();const keep=assetVisibleSet(q);const roots=assetRoots();const build=(a,depth,seen=new Set())=>{const id=String(a[pk('Activa')]);if(seen.has(id))return '';const ns=new Set(seen);ns.add(id);const kids=assetChildren(id).filter(k=>!keep||keep.has(String(k[pk('Activa')])));const expanded=q?true:assetExpanded.has(id);const selectedId=selected&&currentEntity==='Activa'?String(selected[pk('Activa')]):'';let h='<div class="tree-node">';h+='<div class="tree-row '+(selectedId===id?'selected':'')+'" onclick="selectAsset(\''+esc(id).replace(/'/g,"&#39;")+'\')">';h+=kids.length?'<button class="tree-toggle" type="button" onclick="event.stopPropagation();toggleAsset(\''+esc(id).replace(/'/g,"&#39;")+'\')">'+(expanded?'▾':'▸')+'</button>':'<span class="tree-toggle"></span>';h+='<span class="tree-indent" style="flex-basis:'+Math.max(0,depth*18)+'px"></span><span class="tree-name">'+esc(assetName(a))+'</span><span class="tree-id">#'+esc(id)+'</span></div>';if(expanded&&kids.length)h+=kids.map(k=>build(k,depth+1,ns)).join('');h+='</div>';return h};box.innerHTML=roots.filter(a=>!keep||keep.has(String(a[pk('Activa')]))).map(a=>build(a,0)).join('')||'<div class="pad muted">Geen activa gevonden.</div>';$('listTitle').textContent='Activa';$('headerStats').textContent=assetRows.length+' activa';}
function toggleAsset(id){if(assetExpanded.has(String(id)))assetExpanded.delete(String(id));else assetExpanded.add(String(id));renderAssetTree()}
async function selectAsset(id){try{const d=await api('?action=get&entity=Activa&id='+encodeURIComponent(id));selected=d.row;currentEntity='Activa';listEntity='Activa';renderAssetTree();await showDetail('Activa',d.row)}catch(e){$('detail').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
async function renderAssetStatusFilter(){const sel=$('statusFilter');if(!sel)return;const current=sel.value||'active';sel.innerHTML='<option value="__all__">Alle statussen</option><option value="active">Actief</option><option value="inactive">Niet actief</option>';sel.value=['__all__','active','inactive'].includes(current)?current:'active'}
function sortAssetRows(){const mode=$('sortFilter')?.value||'az';const dir=mode==='za'?-1:1;const cmp=(a,b)=>String(assetName(a)||'').localeCompare(String(assetName(b)||''),'nl',{sensitivity:'base',numeric:true})*dir;assetRows.sort(cmp)}
async function loadAssets(){updateSortOptions();renderAssetStatusFilter();try{const status=encodeURIComponent($('statusFilter')?.value||'active');const d=await api('?action=list&entity=Activa&status='+status+'&q='+encodeURIComponent($('search')?.value.trim()||''));assetRows=d.rows||[];assetCategories=lookupIdLabelOptions('Activa','ActivaCatID').map(x=>({ActivaCatID:x.value,ActivaCategorie:x.label}));sortAssetRows();if(!assetExpanded.size)assetRoots().forEach(a=>assetExpanded.add(String(a[pk('Activa')])));renderAssetTree();}catch(e){$('list').innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
window.addEventListener('pageshow',()=>{if(listEntity==='maintenance_plans'){loadMaintenance()}});
async function showListTab(e,b){$('detailTitle').classList.remove('key-detail-title');listEntity=e;currentEntity=null;selected=null;historyStack=[];document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('search').value='';toggleClear('searchbox','search');$('audit').hidden=true;$('detailTitle').textContent='Selecteer een record';$('detailSub').textContent='';$('detail').innerHTML='<div class="notice">Selecteer links een activum. De hiërarchie is inklapbaar.</div>';if(e==='Activa'){await loadAssets()}else{ $('listTitle').textContent=e==='contacts'?'Contacten':'Relaties';load()}}
async function load(){if(listEntity==='Activa'){await loadAssets();return}currentEntity=listEntity;renderStatusFilter();try{const q=encodeURIComponent($('search').value.trim());const status=encodeURIComponent($('statusFilter')?.value||'active');const d=await api('?action=list&entity='+listEntity+'&q='+q+'&status='+status);rows=d.rows||[];renderList()}catch(e){$('list').innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
function renderList(){if(listEntity==='Activa'){sortAssetRows();renderAssetTree();return}updateSortOptions();const p=pk(listEntity);sortRows();$('listTitle').textContent=listEntity==='contacts'?'Contacten':'Relaties';$('headerStats').textContent=rows.length+' resultaten · '+meta.entities[listEntity].count+' totaal';$('list').innerHTML=rows.map((x,i)=>{let title,sub;if(listEntity==='contacts'){title=name(x);sub='Huisnummer '+first(x,['Huisnummer'])+' · Hal '+first(x,['Hal'])+' · '+first(x,['Status','Actief'])}else{title=first(x,['Naam','Alias'])||('Relatie '+x[p]);sub='Relatie · '+first(x,['Actief'])}return `<div class="item ${selected&&String(selected[p])===String(x[p])?'selected':''}" onclick="selectRow(${i})"><strong>${esc(title)}</strong><span>${esc(sub)}</span></div>`}).join('')||'<div class="pad muted">Geen resultaten.</div>';syncListHeader()}
function assetFieldSelect(name,value,options,allowBlank=true){let h='<select class="asset-select" name="'+esc(name)+'">';if(allowBlank)h+='<option value="">— Geen keuze —</option>';for(const o of options){const isObj=o&&typeof o==='object';const v=String(isObj?(o.value??o.id??''):o);const lab=String(isObj?(o.label??o.name??v):o);h+='<option value="'+esc(v)+'" '+(String(value??'')===v?'selected':'')+'>'+esc(lab)+'</option>'}return h+'</select>'}
function assetDateValue(v){return dateInputValue(v)}
function assetDateDisplay(v){const s=assetDateValue(v);if(!s)return '';const [y,m,d]=s.split('-');return d+'-'+m+'-'+y}
function assetMoneyValue(v){if(v===null||v===undefined||v==='')return '';let s=String(v).trim().replace(/\s/g,'').replace(/€/g,'');if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');return s}
function assetMoneyDisplay(v){const n=Number(assetMoneyValue(v));if(!Number.isFinite(n))return String(v??'');return new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(n)}
function assetIsMoney(k){return ['Aanschafwaarde','Af te schrijven','Huidige boekwaarde','Kosten'].some(x=>normKey(x)===normKey(k))}
function assetIsDate(k){return ['Aanschafdatum','Datum ingebruikname'].some(x=>normKey(x)===normKey(k))}
function assetExcluded(k){const n=normKey(k);return ['bewoner','huurder','huuropbrengst','sharepointlink','afbeelding','update','vveguimodifiedat','vveguimodifiedby','legacyjson'].includes(n)||isIdField(k)}
function assetFieldEdit(k,v,row){
  const nk=normKey(k);
  if(nk==='activacatid')return '<div class="field"><label>Categorie</label>'+assetFieldSelect(k,v,assetCategories.map(x=>({value:x.ActivaCatID,label:x.ActivaCategorie})))+'</div>';
  if(nk==='parentactivaid'){
    const id=row?String(row.ActivaID):'';const opts=assetRows.filter(x=>String(x.ActivaID)!==id).sort((a,b)=>assetName(a).localeCompare(assetName(b),'nl')).map(x=>({value:x.ActivaID,label:assetName(x)}));
    return '<div class="field asset-wide-field"><label>Onderdeel van</label>'+assetFieldSelect(k,v,opts)+'</div>';
  }
  if(nk==='functie'){
    let options=lookupOptions('Activa',k)||lookupOptions(currentEntity,k)||[];
    if(!options.length && meta?.lookups?.common)options=lookupOptions('common',k)||[];
    if(!options.length)options=[...new Set(assetRows.map(x=>String(x?.[k]??'').trim()).filter(Boolean))];
    if(v!=='' && !options.some(o=>String(o)===String(v)))options=[String(v),...options];
    return '<div class="field"><label>Functie</label>'+assetFieldSelect(k,v,options,true)+'</div>';
  }
  if(nk==='toestand'){
    let options=lookupOptions('Activa',k)||[];
    if(v!=='' && !options.some(o=>String(o)===String(v)))options=[String(v),...options];
    return '<div class="field"><label>Toestand</label>'+assetFieldSelect(k,v,options,true)+'</div>';
  }
  if(nk==='actief'){
    if(isBoolField(k,v))return '<div class="field"><label>Actief</label><div class="bool-group"><button type="button" class="bool '+(boolState(v)?'active':'')+'" onclick="setBool(this,true,\''+esc(k)+'\',\''+esc(boolValue(true,v))+'\')">Waar</button><button type="button" class="bool false '+(!boolState(v)?'active':'')+'" onclick="setBool(this,false,\''+esc(k)+'\',\''+esc(boolValue(false,v))+'\')">Niet waar</button><input type="hidden" name="'+esc(k)+'" value="'+esc(v??'')+'"></div></div>';
  }
  if(assetIsDate(k))return '<div class="field"><label>'+esc(label(k))+'</label>'+dateEditor(k,v)+'</div>';
  if(assetIsMoney(k))return '<div class="field"><label>'+esc(label(k))+'</label><div class="money-wrap"><span class="money-prefix">€</span><input type="number" step="0.01" inputmode="decimal" name="'+esc(k)+'" value="'+esc(assetMoneyValue(v))+'"></div></div>';
  if(nk==='omschrijving')return '<div class="field full comments-field"><label>Omschrijving</label><textarea name="'+esc(k)+'" rows="2">'+esc(v??'')+'</textarea></div>';
  const wide=nk==='naam';
  return '<div class="field '+(wide?'asset-wide-field':'')+'"><label>'+esc(label(k))+'</label><input name="'+esc(k)+'" value="'+esc(v??'')+'"'+(wide?' style="white-space:nowrap"':'')+'></div>';
}
function assetEditableColumns(row){
  const raw=meta.entities.Activa.columns||[];
  const wanted=['Naam','ParentActivaID','Actief','ActivaCatID','Functie','Fabrikant','Leverancier','Merk','Type','Serienummer','Grootte','Vermogen','Aansluitwaarde','Spanning','Stroomsterkte','Levensduur','Locatie','Toestand','Omschrijving','Aanschafwaarde','Aanschafdatum','Datum ingebruikname','Afschrijftermijn Jaren','Afgeschreven Jaren','Af te schrijven','Huidige boekwaarde','Kosten'];
  const out=[];for(const target of wanted){const a=raw.find(k=>normKey(k)===normKey(target));if(a&&!out.includes(a))out.push(a)}
  return out;
}
function assetImageGallery(images,admin=true){if(!images||!images.length)return '<div class="empty">Geen afbeeldingen opgeslagen.</div>';return '<div class="asset-gallery">'+images.map(im=>{const url=String(im.url||''),title=String(im.Bestandsnaam||im.Titel||'Afbeelding');return '<div class="asset-image-card" style="width:154px;max-width:154px;display:inline-block;vertical-align:top;box-sizing:border-box"><button type="button" class="asset-thumb-button" style="display:block;width:140px;height:100px;padding:0;margin:0;overflow:hidden;border:0;border-radius:6px;background:#f4f6f8;cursor:zoom-in" onclick="openAssetImage(\''+esc(url).replace(/'/g,"\\'")+'\',\''+esc(title).replace(/'/g,"\\'")+'\')" title="Klik voor volledige afbeelding"><img class="asset-thumb" src="'+esc(url)+'" alt="'+esc(title)+'" style="display:block;width:140px;height:100px;object-fit:cover;border-radius:6px"></button><div class="asset-image-name" title="'+esc(String(im.Bestandsnaam||''))+'">'+esc(String(im.Titel||im.Bestandsnaam||'Afbeelding'))+'</div>'+(admin?'<div class="asset-image-actions"><button type="button" class="btn danger" onclick="deleteAssetImage('+esc(String(im.AfbeeldingID))+')">🗑 Deactiveren</button></div>':'')+'</div>'}).join('')+'</div>'}
async function loadAssetImages(id){try{const d=await api('?action=images&entity=Activa&id='+encodeURIComponent(id));return d.images||[]}catch(e){return[]}}
function assetSourceLabel(type){return type==='bron-email'?'E-mail':type==='bron-document'?'Document uit Bestanden':type==='link'?'Link':'Bestand'}
function assetDocumentsSection(documents){return '<div class="section"><div class="section-head">📎 Gekoppelde bronnen</div>'+(documents&&documents.length?'<div class="pad">'+documents.map(d=>'<div class="doc-row"><div style="min-width:0;flex:1"><a href="'+esc(d.url||'#')+'" >'+esc(d.Titel||d.Bestandsnaam||'Bestand')+'</a>'+(d.Bestandsnaam?'<div class="muted">'+esc(d.Bestandsnaam)+'</div>':'')+'</div><span class="muted">'+esc(assetSourceLabel(d.Type))+'</span></div>').join('')+'</div>':'<div class="empty">Geen documenten of e-mails gekoppeld.</div>')+'</div>'}
async function loadAssetDocuments(id){try{const d=await api('?action=documents&entity=Activa&id='+encodeURIComponent(id));return d.documents||[]}catch(e){return[]}}
async function uploadAssetDocuments(id){const input=$('assetDocumentInput');if(!input||!input.files.length){if(input)input.click();return}try{const fd=new FormData();for(const f of input.files)fd.append('documents[]',f);await api('?action=upload_document&entity=Activa&id='+encodeURIComponent(id),{method:'POST',body:fd});assetCurrentDocuments=await loadAssetDocuments(id);beginEdit()}catch(e){$('detail').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
let libraryPickerTimer=null;
function linkLibraryDocument(entity,id){let modal=$('libraryPicker');if(!modal){document.body.insertAdjacentHTML('beforeend','<div id="libraryPicker" role="dialog" aria-modal="true" style="position:fixed;inset:0;background:rgba(23,32,42,.62);display:none;align-items:center;justify-content:center;padding:18px;z-index:100000" onclick="if(event.target===this)closeLibraryPicker()"><div style="width:min(760px,96vw);height:min(78vh,760px);background:#fff;border-radius:12px;border:1px solid #d5e0e8;box-shadow:0 20px 70px rgba(0,0,0,.35);display:flex;flex-direction:column;overflow:hidden"><div class="table-head" style="padding:14px 16px;background:#dcecf8;border-bottom:1px solid #c7dce9;display:flex;align-items:center;gap:10px"><h2 style="margin:0">Document uit Bestanden koppelen</h2><span style="flex:1"></span><button type="button" class="btn" onclick="closeLibraryPicker()">✕ Sluiten</button></div><div class="pad"><div class="searchbox"><input id="libraryPickerSearch" type="search" placeholder="Zoek op titel of bestandsnaam…" oninput="scheduleLibrarySearch()"><button type="button" class="btn primary" onclick="searchLibraryDocuments()">Zoeken</button></div><p class="muted">Het gekozen document blijft centraal in Bestanden opgeslagen.</p></div><div id="libraryPickerResults" style="flex:1;overflow:auto;background:#fff"></div></div></div>');modal=$('libraryPicker')}modal.dataset.entity=entity;modal.dataset.recordId=String(id);modal.style.display='flex';$('libraryPickerSearch').value='';searchLibraryDocuments();setTimeout(()=>$('libraryPickerSearch')?.focus(),0)}
function closeLibraryPicker(){const modal=$('libraryPicker');if(modal)modal.style.display='none'}
function scheduleLibrarySearch(){clearTimeout(libraryPickerTimer);libraryPickerTimer=setTimeout(searchLibraryDocuments,250)}
async function searchLibraryDocuments(){const box=$('libraryPickerResults'),q=$('libraryPickerSearch')?.value.trim()||'';box.innerHTML='<div class="empty">Zoeken…</div>';try{const found=(await api('?action=library_documents&q='+encodeURIComponent(q))).documents||[];box.innerHTML=found.length?'<div class="pad">'+found.map(d=>'<div class="doc-row"><div style="min-width:0;flex:1"><strong>'+esc(d.Titel||d.OrigineleNaam||'Document')+'</strong><div class="muted">'+esc(d.OrigineleNaam||'')+'</div></div><button type="button" class="btn primary small" onclick="chooseLibraryDocument('+esc(String(d.DocumentID))+')">🔗 Koppelen</button></div>').join('')+'</div>':'<div class="empty">Geen documenten gevonden. Upload het document eerst via Bestanden.</div>'}catch(e){box.innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
async function chooseLibraryDocument(documentId){const modal=$('libraryPicker'),entity=modal.dataset.entity,id=modal.dataset.recordId;try{const fd=new FormData();fd.append('document_id',documentId);await api('?action=link_library_document&entity='+encodeURIComponent(entity)+'&id='+encodeURIComponent(id),{method:'POST',body:fd});closeLibraryPicker();if(entity==='Activa')assetCurrentDocuments=await loadAssetDocuments(id);else maintenanceCurrentDocuments=(await api('?action=documents&entity=maintenance_plans&id='+encodeURIComponent(id))).documents||[];beginEdit()}catch(e){$('libraryPickerResults').insertAdjacentHTML('afterbegin','<div class="pad"><div class="err">'+esc(e.message)+'</div></div>')}}
function appConfirm(message,confirmLabel='Verwijderen'){return new Promise(resolve=>{let modal=$('appConfirmModal');if(!modal){document.body.insertAdjacentHTML('beforeend','<div id="appConfirmModal" role="dialog" aria-modal="true" style="position:fixed;inset:0;background:rgba(23,32,42,.62);display:none;align-items:center;justify-content:center;padding:18px;z-index:100001"><div style="width:min(520px,94vw);background:#fff;border:1px solid #d5e0e8;border-radius:12px;box-shadow:0 20px 70px rgba(0,0,0,.38);overflow:hidden"><div style="padding:14px 16px;background:#dcecf8;border-bottom:1px solid #c7dce9"><h2 style="margin:0;font-size:20px">Bevestigen</h2></div><div class="pad" style="padding:18px"><p id="appConfirmMessage" style="margin:0;line-height:1.5"></p><div class="actions" style="margin-top:18px"><button type="button" class="btn" id="appConfirmCancel">Annuleren</button><button type="button" class="btn danger" id="appConfirmOk"></button></div></div></div></div>');modal=$('appConfirmModal')}const finish=value=>{modal.style.display='none';resolve(value)};$('appConfirmMessage').textContent=message;$('appConfirmOk').textContent='🗑 '+confirmLabel;$('appConfirmCancel').onclick=()=>finish(false);$('appConfirmOk').onclick=()=>finish(true);modal.onclick=event=>{if(event.target===modal)finish(false)};modal.style.display='flex';setTimeout(()=>$('appConfirmCancel')?.focus(),0)})}
async function deleteAssetDocument(id,type){const question=type==='link'?'Deze koppeling bij het activum verwijderen? Het centrale document blijft bestaan.':'Dit oude, rechtstreeks bij het activum opgeslagen bestand verwijderen?';if(USER_ROLE!=='admin'||!await appConfirm(question,type==='link'?'Koppeling verwijderen':'Bestand verwijderen'))return;try{await api('?action=delete_document&entity=Activa&document_id='+encodeURIComponent(id),{method:'POST'});assetCurrentDocuments=await loadAssetDocuments(selected[pk('Activa')]);beginEdit()}catch(e){alert(e.message)}}
async function deleteAssetSourceLink(id){if(USER_ROLE!=='admin'||!await appConfirm('Deze koppeling bij het activum verwijderen? De e-mail of het document zelf blijft bestaan.','Koppeling verwijderen'))return;try{await api('?action=delete_source_link&entity=Activa&link_id='+encodeURIComponent(id),{method:'POST'});assetCurrentDocuments=await loadAssetDocuments(selected[pk('Activa')]);beginEdit()}catch(e){alert(e.message)}}

function assetImagesSection(id,images,editable=false){let h='<div class="asset-images"><div class="asset-images-head">🖼️ Afbeeldingen</div><div class="asset-images-body">'+assetImageGallery(images,editable&&USER_ROLE==='admin');if(editable&&USER_ROLE==='admin')h+='<div class="asset-upload"><input id="assetImageInput" name="asset_images" type="file" accept="image/png,image/jpeg,image/bmp" multiple><button type="button" class="btn primary" data-upload-asset-images onclick="uploadAssetImages('+esc(String(id))+')">⬆ Afbeeldingen uploaden</button><span class="muted">PNG, JPEG of BMP · meerdere tegelijk</span></div>';return h+'</div></div>'}
function assetDocumentsEditor(id){const docs=assetCurrentDocuments||[];return '<div class="section"><div class="section-head">📎 Gekoppelde bronnen</div><div class="pad">'+(docs.length?docs.map(d=>{const source=String(d.Type).startsWith('bron-'),type=d.Type==='link'?'link':'bestand',remove=source?'deleteAssetSourceLink('+Number(d.KoppelingID)+')':'deleteAssetDocument('+Number(d.DocumentID)+',\''+type+'\')';return '<div class="doc-row"><div style="min-width:0;flex:1"><a href="'+esc(d.url||'#')+'" >'+esc(d.Titel||d.Bestandsnaam||'Bestand')+'</a>'+(d.Bestandsnaam?'<div class="muted">'+esc(d.Bestandsnaam)+'</div>':'')+'</div><span class="muted">'+esc(assetSourceLabel(d.Type))+'</span><button type="button" class="btn danger small" onclick="'+remove+'">🗑 Koppeling</button></div>'}).join(''):'<div class="empty">Geen documenten of e-mails gekoppeld.</div>')+'<div class="asset-upload"><button type="button" class="btn primary" onclick="linkLibraryDocument(\'Activa\','+esc(String(id))+')">🔗 Document uit Bestanden koppelen</button><span class="muted">Ook e-mails kunnen via de Assistent worden gekoppeld.</span></div></div></div>'}
function assetForm(row){const p=pk('Activa'),req=meta.required?.Activa||[],defaults=row||( ()=>{const d={};const ak=(meta.entities.Activa.columns||[]).find(k=>normKey(k)==='actief');if(ak)d[ak]='Waar';return d})();const cols=assetEditableColumns(defaults);let h='<form id="editForm" data-required="'+esc(req.join('|'))+'"><div class="grid">'+cols.map(k=>assetFieldEdit(k,defaults?.[k]??'',row)).join('')+'</div>';
  if(row?.[p]!=null){h+='<input type="hidden" name="'+esc(p)+'" value="'+esc(String(row[p]))+'">';h+=assetImagesSection(row[p],assetCurrentImages||[],true);h+=assetDocumentsEditor(row[p]);}
  else {h+='<div class="asset-images"><div class="asset-images-head">🖼️ Afbeeldingen</div><div class="asset-images-body"><div class="notice" style="margin:0">Sla het nieuwe activum eerst op; daarna kunnen één of meerdere afbeeldingen worden toegevoegd.</div></div></div>';h+='<div class="section"><div class="section-head">📎 Bestanden</div><div class="empty">Sla het nieuwe activum eerst op; daarna kunnen bestanden worden toegevoegd.</div></div>';}
  h+='<div class="actions"><button type="button" class="btn" onclick="cancelEdit()">Annuleren</button>'+(row&&row[p]!=null&&USER_ROLE==='admin'?'<button type="button" class="btn danger" onclick="deleteRecord(\'Activa\',\''+esc(String(row[p]))+'\')">🗑 Deactiveren</button>':'')+'<button type="submit" class="btn primary">💾 Opslaan</button></div></form>';return h;
}
let assetCurrentImages=[];let assetCurrentDocuments=[];
async function renderAssetRelated(id){const box=$('related');try{const d=await api('?action=related&entity=Activa&id='+encodeURIComponent(id));let h='';const m=d.related?.maintenance_plans||[],k=d.related?.keys||[];h+='<div class="related-head">🔧 Onderhoudsplannen</div>';if(m.length){h+='<div class="right-table-wrap"><table class="asset-related-table"><thead><tr><th>Onderhoudsplan</th><th>Status</th><th>Planjaar</th><th>Uitvoeringsjaar</th><th>Datum inspectie</th></tr></thead><tbody>';m.forEach(r=>{const mid=String(r[pk('maintenance_plans')]??'');const nm=maintenanceName(r)||('Onderhoudsplan '+(mid||''));h+='<tr><td>'+(mid?'<a href="#" class="maintenance-related-link" data-entity="maintenance_plans" data-id="'+esc(mid)+'" onclick="event.preventDefault();openMaintenanceRelated(this)">'+esc(nm)+'</a>':esc(nm))+'</td><td>'+esc(first(r,['Status']))+'</td><td>'+esc(first(r,['Planjaar']))+'</td><td>'+esc(first(r,['UitvoeringsJaar']))+'</td><td>'+esc(dateDisplayValue(first(r,['DatumInspectie'])))+'</td></tr>'});h+='</tbody></table></div>'}else h+='<div class="empty">Geen gekoppelde onderhoudsplannen.</div>';h+='<div class="related-head">🔑 Sleutels</div>';if(k.length){const cols=keyColumns();h+='<div class="right-table-wrap"><table class="asset-related-table"><thead><tr>'+cols.map(x=>'<th>'+esc(label(x))+'</th>').join('')+'</tr></thead><tbody>';k.forEach(r=>{const kid=String(r[pk('Sleutels')]??'');h+='<tr>'+cols.map((x,i)=>{const v=tableCellValue('Sleutels',r,x);if(i===0&&kid)return '<td><a href="#" class="maintenance-related-link" data-entity="Sleutels" data-id="'+esc(kid)+'" onclick="event.preventDefault();openKeyRelated(this)">'+esc(v||'—')+'</a></td>';return '<td>'+esc(v||'—')+'</td>'}).join('')+'</tr>'});h+='</tbody></table></div>'}else h+='<div class="empty">Geen gekoppelde sleutels.</div>';box.innerHTML=h}catch(e){box.innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
function renderAssetView(r,images,documents){
  const cols=assetEditableColumns(r);let h='<div class="section"><div class="section-head">📋 Gegevens</div><div class="view-grid">';
  for(const k of cols){const nk=normKey(k);if(assetExcluded(k) && !['parentactivaid','activacatid'].includes(nk))continue;const v=r?.[k]??'';let val=esc(v);let cls='';if(assetIsMoney(k)){val=esc(assetMoneyDisplay(v));cls='currency-view'}else if(assetIsDate(k)){val=esc(assetDateDisplay(v));cls='date-view'}const wide=nk==='naam'||nk==='parentactivaid';const full=nk==='omschrijving'||String(v).length>120;let labelText=label(k);if(nk==='parentactivaid')labelText='Onderdeel van';if(nk==='activacatid')labelText='Categorie';
    if(nk==='parentactivaid'){const parent=first(r,['ParentActivaID']);const pa=parent?assetRows.find(x=>String(x.ActivaID)===String(parent)):null;val=esc(pa?assetName(pa):(parent?'Activum #'+parent:'—'));}
    if(nk==='activacatid'){const cat=first(r,['ActivaCatID']);const ca=cat?assetCategories.find(x=>String(x.ActivaCatID)===String(cat)):null;val=esc(ca?ca.ActivaCategorie:(cat||''));}
    h+='<div class="view-field '+(wide?'asset-wide-value ':'')+(full?'full ':'')+(nk==='omschrijving'?'comments-field ':'')+'"><label>'+esc(labelText)+'</label><div class="view-value '+cls+'">'+(val||'—')+'</div></div>';
  }
  h+='</div></div>'+assetImagesSection(r[pk('Activa')],images,false)+assetDocumentsSection(documents||[])+(USER_ROLE==='admin'?'<div class="actions"><button class="btn primary" onclick="beginEdit()">✏️ Wijzigen</button></div>':'');return h;
}
async function selectAsset(id){try{const d=await api('?action=get&entity=Activa&id='+encodeURIComponent(id));selected=d.row;currentEntity='Activa';listEntity='Activa';renderAssetTree();await showDetail('Activa',d.row)}catch(e){$('detail').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
async function renderAssetStatusFilter(){const sel=$('statusFilter');if(!sel)return;const current=sel.value||'active';sel.innerHTML='<option value="__all__">Alle statussen</option><option value="active">Actief</option><option value="inactive">Niet actief</option>';sel.value=['__all__','active','inactive'].includes(current)?current:'active'}
function sortAssetRows(){const mode=$('sortFilter')?.value||'az';const dir=mode==='za'?-1:1;const cmp=(a,b)=>String(assetName(a)||'').localeCompare(String(assetName(b)||''),'nl',{sensitivity:'base',numeric:true})*dir;assetRows.sort(cmp)}
async function loadAssets(){updateSortOptions();renderAssetStatusFilter();try{const status=encodeURIComponent($('statusFilter')?.value||'active');const d=await api('?action=list&entity=Activa&status='+status+'&q='+encodeURIComponent($('search')?.value.trim()||''));assetRows=d.rows||[];assetCategories=lookupIdLabelOptions('Activa','ActivaCatID').map(x=>({ActivaCatID:x.value,ActivaCategorie:x.label}));sortAssetRows();if(!assetExpanded.size)assetRoots().forEach(a=>assetExpanded.add(String(a[pk('Activa')])));renderAssetTree();}catch(e){$('list').innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
function maintenanceName(r){const nm=String(first(r,['Naam'])||'').trim();const aid=first(r,['ActivaID','ActivaId']);const a=(meta?.maintenanceOptions?.assets||[]).find(x=>String(x.id)===String(aid));const an=String(a?.label||'').trim();if(nm&&an)return nm+' '+an;if(nm)return nm;if(an)return an;return 'Onderhoudsplan #'+r[pk('maintenance_plans')]}
function maintenanceAssetLabelById(id){const a=(meta?.maintenanceOptions?.assets||[]).find(x=>String(x.id)===String(id));return String(a?.label||'').trim()}
function maintenanceOpts(arr,value){return '<option value="">— Geen keuze —</option>'+((arr||[]).map(o=>{const id=String(o.id??o.value??'');const lab=String(o.label??o.name??o.code??id);return '<option value="'+esc(id)+'" '+(String(value??'')===id?'selected':'')+'>'+esc(lab)+'</option>'}).join(''))}
function maintenancePercentValue(v){return String(v??'').trim().replace('%','').replace(',','.')}
function maintenancePercentDisplay(v){const x=maintenancePercentValue(v);return x===''?'':x+' %'}
function maintenanceField(k,v){const n=normKey(k);if(n==='status')return '<div class="field"><label>Status</label><select name="'+esc(k)+'">'+maintenanceOpts(meta.statusOptions?.maintenance_plans||[],v)+'</select></div>';if(n==='activaid')return '<div class="field"><label>Activum</label><select name="'+esc(k)+'">'+maintenanceOpts(meta.maintenanceOptions?.assets,v)+'</select></div>';if(n==='uitvoerder')return '<div class="field"><label>Uitvoerder</label><select name="'+esc(k)+'">'+maintenanceOpts(meta.maintenanceOptions?.relations,v)+'</select></div>';if(n==='onderhoudscategorie')return '<div class="field"><label>Onderhoudscategorie</label><select name="'+esc(k)+'">'+maintenanceOpts(meta.maintenanceOptions?.categories,v)+'</select></div>';if(n==='stabucode'){let opts=(meta.maintenanceOptions?.stabu||[]).map(x=>({id:x.code,label:String(x.code)+(x.label?' — '+x.label:'')}));if(v!==''&&!opts.some(x=>String(x.id)===String(v)))opts.unshift({id:v,label:String(v)});return '<div class="field"><label>STABU-code</label><select name="'+esc(k)+'">'+maintenanceOpts(opts,v)+'</select></div>'}if(n==='mjopreferentie'){let opts=[...(meta.maintenanceOptions?.mjop||[])];if(v!==''&&!opts.some(x=>String(x.id)===String(v)))opts.unshift({id:v,label:String(v)+' — bestaande verwijzing'});return '<div class="field"><label>MJOP-referentie</label><select name="'+esc(k)+'">'+maintenanceOpts(opts,v)+'</select></div>'}if(n==='indexering')return '<div class="field"><label>Indexering</label><div class="percent-wrap"><input type="number" min="-100" max="1000" step="0.01" name="'+esc(k)+'" value="'+esc(maintenancePercentValue(v))+'"><span>%</span></div></div>';if(n==='planbedrag')return '<div class="field"><label>Planbedrag</label><div class="money-wrap"><span class="money-prefix">€</span><input type="number" step="0.01" name="'+esc(k)+'" value="'+esc(assetMoneyValue(v))+'"></div></div>';if(n==='planyaan'||n==='uitvoeringsjaar')return '<div class="field"><label>'+esc(label(k))+'</label><input type="number" min="2000" max="2200" step="1" name="'+esc(k)+'" value="'+esc(v??'')+'"></div>';if(isDateFieldName(k))return '<div class="field"><label>'+esc(label(k))+'</label>'+dateEditor(k,v)+'</div>';if(n==='actief'&&isBoolField(k,v))return '<div class="field"><label>Actief</label><div class="bool-group"><button type="button" class="bool '+(boolState(v)?'active':'')+'" onclick="setBool(this,true,\''+esc(k)+'\',\''+esc(boolValue(true,v))+'\')">Waar</button><button type="button" class="bool false '+(!boolState(v)?'active':'')+'" onclick="setBool(this,false,\''+esc(k)+'\',\''+esc(boolValue(false,v))+'\')">Niet waar</button><input type="hidden" name="'+esc(k)+'" value="'+esc(v??'')+'"></div></div>';const area=n==='werkomschrijving'||n==='opmerkingen';const full=n==='naam'||n==='activaid'||area;const wide=n==='stabucode';return '<div class="field '+(full?'full ':'')+(wide?'maintenance-stabu ':'')+'"><label>'+esc(label(k))+'</label>'+(area?'<textarea class="maintenance-textarea" name="'+esc(k)+'" rows="2">'+esc(v??'')+'</textarea>':'<input name="'+esc(k)+'" value="'+esc(v??'')+'">')+'</div>'}
function maintenanceColumns(){const raw=meta.entities.maintenance_plans.columns||[];const wanted=['Naam','ActivaID','Uitvoerder','OnderhoudsCategorie','Status','DatumInspectie','Planjaar','UitvoeringsJaar','PlanBedrag','Indexering','StabuCode','MJOPReferentie','Actief','Werkomschrijving','Opmerkingen'];const out=[];for(const w of wanted){const x=raw.find(k=>normKey(k)===normKey(w));if(x&&!out.includes(x))out.push(x)}return out}
function maintenanceDocumentsEditor(id){const docs=maintenanceCurrentDocuments||[];return '<div class="section"><div class="section-head">📎 Gekoppelde documenten</div><div class="pad">'+(docs.length?docs.map(d=>{const type=d.Type==='link'?'link':'bestand';return '<div class="doc-row"><a href="'+esc(d.url||'#')+'" >'+esc(d.Titel||d.Bestandsnaam||d.Url||'Document')+'</a><span class="muted">'+esc(type==='link'?'Bibliotheeklink':'Bestaand bestand')+'</span><button type="button" class="btn danger small" onclick="deleteMaintenanceDocument('+esc(String(d.DocumentID))+',\''+type+'\')">🗑 '+(type==='link'?'Koppeling':'Bestand')+'</button></div>'}).join(''):'<div class="empty">Geen documenten gekoppeld.</div>')+'<div class="asset-upload"><button type="button" class="btn primary" onclick="linkLibraryDocument(\'maintenance_plans\','+esc(String(id))+')">🔗 Document uit Bestanden koppelen</button><span class="muted">Het document blijft centraal opgeslagen.</span></div></div></div>'}
function maintenanceForm(row){const p=pk('maintenance_plans');let h='<form id="editForm"><div class="grid">'+maintenanceColumns().map(k=>maintenanceField(k,row?.[k]??'')).join('')+'</div>';if(row?.[p]!=null)h+=maintenanceDocumentsEditor(row[p]);else h+='<div class="section"><div class="section-head">📎 Documenten</div><div class="empty">Sla het nieuwe onderhoudsplan eerst op; daarna kunnen documenten worden toegevoegd.</div></div>';h+='<div class="actions"><button type="button" class="btn" onclick="cancelEdit()">Annuleren</button>'+(row&&row[p]!=null?'<button type="button" class="btn danger" onclick="deleteRecord(\'maintenance_plans\',\''+esc(String(row[p]))+'\')">🗑 Deactiveren</button>':'')+'<button type="submit" class="btn primary">💾 Opslaan</button></div></form>';return h}
let maintenanceCurrentDocuments=[];
async function loadMaintenance(){currentEntity='maintenance_plans';const sf=$('statusFilter');if(sf&&(!sf.value||sf.value==='active'||sf.value==='inactive'))sf.value='__all__';renderStatusFilter();try{const q=encodeURIComponent($('search').value.trim());const status=encodeURIComponent($('statusFilter')?.value||'active');const d=await api('?action=list&entity=maintenance_plans&q='+q+'&status='+status);rows=d.rows||[];renderMaintenanceList()}catch(e){$('list').innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
function renderMaintenanceList(){updateSortOptions();$('listTitle').textContent='Onderhoudsplannen';$('headerStats').textContent=rows.length+' resultaten · '+meta.entities.maintenance_plans.count+' totaal';const p=pk('maintenance_plans');sortRows();$('list').innerHTML=rows.map((x,i)=>'<div class="item '+(selected&&String(selected[p])===String(x[p])?'selected':'')+'" onclick="selectMaintenance('+i+')"><strong>'+esc(maintenanceName(x))+'</strong><span>'+esc(first(x,['Status'])||'—')+' · '+esc(first(x,['Planjaar'])||'—')+' · '+esc(first(x,['ActivaID'])?'Activum #'+first(x,['ActivaID']):'Geen activum')+'</span></div>').join('')||'<div class="pad muted">Geen onderhoudsplannen gevonden.</div>';syncListHeader()}
async function selectMaintenance(i){const x=rows[i];try{const d=await api('?action=get&entity=maintenance_plans&id='+encodeURIComponent(x[pk('maintenance_plans')]));selected=d.row;currentEntity='maintenance_plans';await showMaintenanceDetail(d.row)}catch(e){$('detail').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
async function showMaintenanceDetail(r){selected=r;currentEntity='maintenance_plans';$('audit').hidden=false;$('audit').innerHTML=auditHTML('maintenance_plans',r);$('detailTitle').textContent=maintenanceName(r);$('detailSub').textContent='Onderhoudsplan #'+r[pk('maintenance_plans')];try{const d=await api('?action=related&entity=maintenance_plans&id='+encodeURIComponent(r[pk('maintenance_plans')]));maintenanceCurrentDocuments=d.related.documents||[];const asset=d.related.asset,rel=d.related.relation;let h='<div class="section"><div class="section-head">📋 Gegevens</div><div class="view-grid">';for(const k of maintenanceColumns()){const n=normKey(k);let v=r?.[k]??'',shown=v;if(n==='activaid')shown=asset?maintenanceAssetName(asset):'—';if(n==='uitvoerder')shown=rel?first(rel,['Naam','Alias']):'—';if(n==='indexering')shown=maintenancePercentDisplay(v);if(n==='planbedrag')shown=assetMoneyDisplay(v);if(n==='onderhoudscategorie'){const o=(meta.maintenanceOptions?.categories||[]).find(x=>String(x.id)===String(v));shown=o?o.label:v}if(n==='stabucode'){const o=(meta.maintenanceOptions?.stabu||[]).find(x=>String(x.code)===String(v));shown=o?String(o.code)+(o.label?' — '+o.label:''):v}if(isDateFieldName(k))shown=dateDisplayValue(v);h+='<div class="view-field '+((n==='naam'||n==='activaid'||n==='werkomschrijving'||n==='opmerkingen')?'full ':'')+(n==='stabucode'?'maintenance-stabu ':'')+'"><label>'+esc(label(k))+'</label><div class="view-value">'+esc(shown||'—')+'</div></div>'}h+='</div></div>';h+='<div class="section"><div class="section-head">📎 Documenten</div>'+(maintenanceCurrentDocuments.length?'<div class="pad">'+maintenanceCurrentDocuments.map(d=>'<div class="doc-row"><a href="'+esc(d.url||'#')+'" >'+esc(d.Titel||d.Bestandsnaam||d.Url||'Document')+'</a><span class="muted">'+esc(d.Type==='link'?'Link':'Bestand')+'</span></div>').join('')+'</div>':'<div class="empty">Geen bestanden of links gekoppeld.</div>')+'</div>';const aid=asset?asset[pk('Activa')]:'';const rid=rel?rel[pk('relations')]:'';const alabel=asset?maintenanceAssetName(asset):'Geen activum gekoppeld.';const rlabel=rel?first(rel,['Naam','Alias']):'Geen uitvoerder gekoppeld.';h+='<div class="section"><div class="section-head">🔗 Gekoppelde gegevens</div><div class="related-grid"><div class="rel-card"><strong>🏢 Activum</strong><span>'+((aid&&asset)?'<a href="#" class="maintenance-related-link" data-entity="Activa" data-id="'+esc(String(aid))+'" onclick="event.preventDefault();openMaintenanceRelated(this)">'+esc(alabel)+'</a>':esc(alabel))+'</span></div><div class="rel-card"><strong>👷 Uitvoerder</strong><span>'+((rid&&rel)?'<a href="#" class="maintenance-related-link" data-entity="relations" data-id="'+esc(String(rid))+'" onclick="event.preventDefault();openMaintenanceRelated(this)">'+esc(rlabel)+'</a>':esc(rlabel))+'</span></div></div></div>';if(USER_ROLE==='admin')h+='<div class="actions"><button class="btn primary" onclick="beginEdit()">✏️ Wijzigen</button></div>';$('detail').innerHTML=h;syncListHeader()}catch(e){$('detail').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
function openMaintenanceRelated(el){if(!el?.dataset?.entity||!el?.dataset?.id)return;return openEntity(el.dataset.entity,el.dataset.id,true)}
function maintenanceAssetName(a){return first(a,['Naam'])||('Activum #'+a?.[pk('Activa')])}
async function uploadMaintenanceDocuments(id){const input=$('maintenanceDocumentInput');if(!input||!input.files.length){if(input)input.click();return}const fd=new FormData();for(const f of input.files)fd.append('documents[]',f);try{await api('?action=upload_document&entity=maintenance_plans&id='+encodeURIComponent(id),{method:'POST',body:fd});maintenanceCurrentDocuments=(await api('?action=documents&entity=maintenance_plans&id='+encodeURIComponent(id))).documents||[];beginEdit()}catch(e){$('detail').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
