async function deleteMaintenanceDocument(id,type){const question=type==='link'?'Deze koppeling bij het onderhoudsplan verwijderen? Het centrale document blijft bestaan.':'Dit oude, rechtstreeks bij het onderhoudsplan opgeslagen bestand verwijderen?';if(USER_ROLE!=='admin'||!await appConfirm(question,type==='link'?'Koppeling verwijderen':'Bestand verwijderen'))return;try{await api('?action=delete_document&entity=maintenance_plans&document_id='+encodeURIComponent(id),{method:'POST'});maintenanceCurrentDocuments=(await api('?action=documents&entity=maintenance_plans&id='+encodeURIComponent(selected[pk('maintenance_plans')]))).documents||[];beginEdit()}catch(e){alert(e.message)}}
async function showMaintenanceNew(){currentEntity='maintenance_plans';selected=null;maintenanceCurrentDocuments=[];$('audit').hidden=true;$('detailTitle').textContent='Nieuw onderhoudsplan';$('detailSub').textContent='Nieuw record';$('detail').innerHTML=maintenanceForm(null);$('editForm').onsubmit=e=>{e.preventDefault();saveMaintenanceRecord(null)}}
async function saveMaintenanceRecord(id){const form=$('editForm'),o={};for(const el of form.elements)if(el.name&&el.type!=='file')o[el.name]=el.dataset.dateField==='1'?dateInputValue(el.value):el.value;try{const d=await api('?action=save&entity=maintenance_plans'+(id!=null?'&id='+encodeURIComponent(id):''),{method:'POST',body:JSON.stringify(o)});const planId=d.id;if(form.elements['maintenance_documents']?.files?.length){const fd=new FormData();for(const f of form.elements['maintenance_documents'].files)fd.append('documents[]',f);await api('?action=upload_document&entity=maintenance_plans&id='+encodeURIComponent(planId),{method:'POST',body:fd})}meta=await api('?action=meta');listEntity='maintenance_plans';currentEntity='maintenance_plans';const fresh=await api('?action=get&entity=maintenance_plans&id='+encodeURIComponent(planId));selected=fresh.row;await loadMaintenance();await showMaintenanceDetail(fresh.row);$('detail').insertAdjacentHTML('afterbegin','<div class="okmsg">✓ Onderhoudsplan opgeslagen.</div>')}catch(e){$('detail').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
function resetModuleControls(e){const sh=$('search'),q=$('question'),tv=$('tableViewBtn');if(sh){sh.placeholder=e==='contacts'?'Zoek naam, huisnummer, telefoon of e-mail…':e==='relations'?'Zoek naam, alias of contact…':e==='Activa'?'Zoek activum, functie of omschrijving…':e==='maintenance_plans'?'Zoek naam, status, jaar of activum…':e==='Sleutels'?'Zoek sleutelnummer, functie, locatie of uitgeleend aan…':'Zoek…'}if(q)q.placeholder=e==='contacts'?'Bijv. wie woont op huisnummer 320?':e==='relations'?'Bijv. welke relatie is gekoppeld aan contact…?':e==='Activa'?'Bijv. waar staat de liftinstallatie?':e==='maintenance_plans'?'Bijv. welke onderhoudsplannen lopen in 2026?':e==='Sleutels'?'Bijv. welke sleutel is uitgeleend?':'Vraag / zoekopdracht';if(tv){tv.textContent='☷ Lijstweergave';tv.onclick=openTableView}}
async function showListTab(e,b){$('detailTitle').classList.remove('key-detail-title');listEntity=e;currentEntity=null;selected=null;historyStack=[];document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));if(b)b.classList.add('active');$('search').value='';toggleClear('searchbox','search');resetModuleControls(e);$('audit').hidden=true;$('detailTitle').textContent=e==='meetings'?'Selecteer een vergadering':'Selecteer een record';$('detailSub').textContent='';$('detail').innerHTML='<div class="notice">'+(e==='meetings'?'Selecteer een vergadering.':'Selecteer links een record.')+'</div>';if(e==='Activa'){ $('listTitle').textContent='Activa'; await loadAssets();return}if(e==='maintenance_plans'){ $('listTitle').textContent='Onderhoudsplannen'; await loadMaintenance();return}if(e==='meetings'){await loadMeetings();return}if(e==='Sleutels'){ $('listTitle').textContent='Sleutels'; await loadKeys();return}$('listTitle').textContent=e==='contacts'?'Contacten':'Relaties';await load()}
async function load(){if(listEntity==='Activa'){await loadAssets();return}if(listEntity==='maintenance_plans'){await loadMaintenance();return}if(listEntity==='meetings'){await loadMeetings();return}if(listEntity==='Sleutels'){await loadKeys();return}currentEntity=listEntity;renderStatusFilter();try{const q=encodeURIComponent($('search').value.trim());const status=encodeURIComponent($('statusFilter')?.value||'active');const d=await api('?action=list&entity='+listEntity+'&q='+q+'&status='+status);rows=d.rows||[];renderList()}catch(e){$('list').innerHTML='<div class="pad"><div class="err">'+esc(e.message)+'</div></div>'}}
function renderList(){if(listEntity==='Activa'){sortAssetRows();renderAssetTree();return}if(listEntity==='maintenance_plans'){renderMaintenanceList();return}if(listEntity==='meetings'){renderMeetingsList();return}if(listEntity==='Sleutels'){renderKeysList();return}updateSortOptions();if(currentEntity==='addresses'){ $('listTitle').textContent='Adres'; $('headerStats').textContent='1 resultaat · 1 totaal'; const title=selected?addressTitle(selected,deepContact,deepRelation):'Adres'; const sub=selected?addressSub(selected):''; $('list').innerHTML=selected?`<div class="item selected"><strong>${esc(title)}</strong><span>${esc(sub)}</span></div>`:'<div class="pad muted">Geen adres geselecteerd.</div>';syncListHeader();return;}const p=pk(listEntity);sortRows();$('listTitle').textContent=listEntity==='contacts'?'Contacten':'Relaties';$('headerStats').textContent=rows.length+' resultaten · '+meta.entities[listEntity].count+' totaal';$('list').innerHTML=rows.map((x,i)=>{let title,sub;if(listEntity==='contacts'){title=name(x);sub='Huisnummer '+first(x,['Huisnummer'])+' · Hal '+first(x,['Hal'])+' · '+first(x,['Status','Actief'])}else{title=first(x,['Naam','Alias'])||('Relatie '+x[p]);sub='Relatie · '+first(x,['Actief'])}return `<div class="item ${selected&&String(selected[p])===String(x[p])?'selected':''}" onclick="selectRow(${i})"><strong>${esc(title)}</strong><span>${esc(sub)}</span></div>`}).join('')||'<div class="pad muted">Geen resultaten.</div>';syncListHeader()}
async function showDetail(entity,r){$('detailTitle').classList.remove('key-detail-title');currentEntity=entity;selected=r;$('audit').hidden=false;$('audit').innerHTML=auditHTML(entity,r);if(entity==='maintenance_plans'){await showMaintenanceDetail(r);return}if(entity==='Sleutels'){showKeyDetail(r);return}if(entity==='Activa'){currentEntity='Activa';selected=r;$('detailTitle').textContent=assetName(r)+' — detail';$('detailSub').textContent='Activum #'+r[pk('Activa')];assetCurrentImages=await loadAssetImages(r[pk('Activa')]);assetCurrentDocuments=await loadAssetDocuments(r[pk('Activa')]);$('detail').innerHTML=renderAssetView(r,assetCurrentImages,assetCurrentDocuments)+'<div id="related" class="related"><div class="related-head">🔗 Gerelateerde gegevens</div><div class="empty">Gegevens laden…</div></div>';await renderAssetRelated(r[pk('Activa')]);return}let title,sub;if(entity==='contacts'){title=name(r);sub='Contactrecord'}else if(entity==='relations'){title=first(r,['Naam','Alias'])||('Relatie '+r[pk(entity)]);sub='Relatierecord'}else{const d=await api('?action=related&entity=addresses&id='+encodeURIComponent(r[pk(entity)]));deepContact=d.related.contacts?.[0]||null;deepRelation=d.related.relations?.[0]||null;title=addressTitle(r,deepContact,deepRelation);sub='Adresrecord'}$('detailTitle').textContent=title;$('detailSub').textContent=sub;$('detail').innerHTML=renderView(entity,r)+'<div id="related" class="related"><div class="related-head">🔗 Gekoppelde gegevens</div><div class="empty">Gegevens laden…</div></div>';try{const d=await api('?action=related&entity='+entity+'&id='+encodeURIComponent(r[pk(entity)]));renderRelated(entity,d.related)}catch(e){$('related').innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
