 try{const d=await api('?action=related&entity='+entity+'&id='+encodeURIComponent(id));if(request!==detailRequest||currentEntity!==entity||String(selected?.[pk(entity)]??'')!==id)return;renderRelated(entity,d.related)}catch(e){if(request===detailRequest&&$('related'))$('related').innerHTML='<div class="err">'+esc(e.message)+'</div>'}
}
function openAssetImage(url,title){let lb=document.getElementById('assetLightbox');if(!lb){document.body.insertAdjacentHTML('beforeend','<div id="assetLightbox" class="asset-lightbox" role="dialog" aria-modal="true" aria-hidden="true" onclick="if(event.target===this)closeAssetImage()"><div class="asset-lightbox-card"><button type="button" class="asset-lightbox-close" aria-label="Sluiten" onclick="closeAssetImage()">×</button><img id="assetLightboxImg" alt=""><div id="assetLightboxCaption" class="asset-lightbox-caption"></div></div></div>');lb=document.getElementById('assetLightbox')}const img=document.getElementById('assetLightboxImg');const cap=document.getElementById('assetLightboxCaption');if(!img||!cap)return;img.src=url;img.alt=title||'Afbeelding';cap.textContent=title||'';lb.classList.add('open');lb.setAttribute('aria-hidden','false')}
function closeAssetImage(){const lb=document.getElementById('assetLightbox');if(!lb)return;lb.classList.remove('open');lb.setAttribute('aria-hidden','true');const img=document.getElementById('assetLightboxImg');if(img)img.src=''}
async function uploadAssetImages(id){const input=$('assetImageInput');if(!input||!input.files.length){if(input)input.click();return;}const btn=document.querySelector('[data-upload-asset-images]');if(btn)btn.disabled=true;const fd=new FormData();for(const f of input.files)fd.append('images[]',f);try{await api('?action=upload_image&entity=Activa&id='+encodeURIComponent(id),{method:'POST',body:fd});assetCurrentImages=await loadAssetImages(id);await showDetail('Activa',selected);beginEdit();}catch(e){$('detail').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>');}finally{if(btn)btn.disabled=false}}
async function deleteAssetImage(id){if(USER_ROLE!=='admin'||!confirm('Deze afbeelding verwijderen?'))return;try{await api('?action=delete_image&entity=Activa&image_id='+encodeURIComponent(id),{method:'POST'});if(selected){assetCurrentImages=await loadAssetImages(selected[pk('Activa')]);beginEdit()}}catch(e){alert(e.message)}}
function beginEdit(){if(USER_ROLE!=='admin')return;if(currentEntity==='Activa'){$('detail').innerHTML=assetForm(selected);autoSizeTextareas($('detail'));$('editForm').onsubmit=e=>{e.preventDefault();saveRecord('Activa',selected?.[pk('Activa')])};return}if(currentEntity==='maintenance_plans'){$('detail').innerHTML=maintenanceForm(selected);autoSizeTextareas($('detail'));$('editForm').onsubmit=e=>{e.preventDefault();saveMaintenanceRecord(selected?.[pk('maintenance_plans')])};return}if(currentEntity==='Sleutels'){beginKeyEdit();return}$('detail').innerHTML=formFor(currentEntity,selected);autoSizeTextareas($('detail'));$('editForm').onsubmit=e=>{e.preventDefault();saveRecord(currentEntity,selected?.[pk(currentEntity)])}}
function newRecord(){if(USER_ROLE!=='admin')return;if(listEntity==='Activa'){currentEntity='Activa';selected=null;assetCurrentImages=[];assetCurrentDocuments=[];$('audit').hidden=true;$('detailTitle').textContent='Nieuw activum';$('detailSub').textContent='Nieuw record';$('detail').innerHTML=assetForm(null);autoSizeTextareas($('detail'));$('editForm').onsubmit=e=>{e.preventDefault();saveRecord('Activa',null)};return}if(listEntity==='maintenance_plans'){showMaintenanceNew();return}if(listEntity==='meetings'){newMeetingRecord();return}if(listEntity==='Sleutels'){newKeyRecord();return}currentEntity=listEntity;selected=null;pendingParent=null;$('audit').hidden=true;$('detailTitle').textContent='Nieuw '+(listEntity==='contacts'?'contact':'relatie');$('detailSub').textContent='Nieuw record';$('detail').innerHTML=formFor(listEntity,null);autoSizeTextareas($('detail'));$('editForm').onsubmit=e=>{e.preventDefault();saveRecord(listEntity,null)}}
async function saveRecord(entity,id){if(entity==='Activa'&&(id===null||id===undefined||id==='')){const p=pk('Activa');const hidden=$('editForm')?.elements?.[p];const fallback=hidden?.value||selected?.[p]||'';if(String(fallback).trim()!=='')id=String(fallback)}const form=$('editForm'),required=(form.dataset.required||'').split('|').filter(Boolean),missing=[];for(const k of required){const el=form.elements[k];if(el&&!String(el.value||'').trim()){el.classList.add('required-warning');missing.push(label(k))}}if(missing.length){$('detail').insertAdjacentHTML('afterbegin','<div class="warn">⚠️ Verplichte velden ontbreken: '+esc(missing.join(', '))+'</div>');return}const o={};for(const el of form.elements)if(el.name&&el.type!=='file')o[el.name]=el.dataset.dateField==='1'?dateInputValue(el.value):el.value;try{let path='?action=save&entity='+entity+(id!=null?'&id='+encodeURIComponent(id):'');if(id==null&&pendingParent){if(pendingParent.contactId)path+='&parent_contact_id='+encodeURIComponent(pendingParent.contactId);if(pendingParent.relationId)path+='&parent_relation_id='+encodeURIComponent(pendingParent.relationId)}const d=await api(path,{method:'POST',body:JSON.stringify(o)});if(entity==='Activa'){const fileInput=form.elements['asset_images'];if(fileInput&&fileInput.files&&fileInput.files.length){await uploadAssetImages(d.id)}const docInput=form.elements['asset_documents'];if(docInput&&docInput.files&&docInput.files.length){await uploadAssetDocuments(d.id)}}meta=await api('?action=meta');pendingParent=null;listEntity=entity;await load();const fresh=await api('?action=get&entity='+entity+'&id='+encodeURIComponent(d.id));selected=fresh.row;currentEntity=entity;await showDetail(entity,fresh.row);const msg='✓ Mutatie opgeslagen door '+esc(meta.user.name)+'.';$('detail').insertAdjacentHTML('afterbegin','<div class="okmsg">'+msg+'</div>')}catch(e){$('detail').insertAdjacentHTML('afterbegin','<div class="err">'+esc(e.message)+'</div>')}}
function cancelEdit(){if(currentEntity==='maintenance_plans'&&selected){showMaintenanceDetail(selected);return}if(selected)showDetail(currentEntity,selected)}
const renderRelatedBeforeProjects=renderRelated;
renderRelated=function(entity,relatedData){renderRelatedBeforeProjects(entity,relatedData);if(entity!=='relations'||!selected)return;const relationId=Number(selected[pk('relations')]);const container=$('related');if(!container)return;const block=document.createElement('div');block.id='relationProjects';block.innerHTML='<div class="related-head">📋 Projecten als uitvoerende firma</div><div class="related-grid"><div class="empty">Projecten laden…</div></div>';container.appendChild(block);fetch('project_api.php?action=relation_projects&id='+relationId,{credentials:'same-origin',cache:'no-store'}).then(response=>response.json()).then(data=>{if(Number(selected?.[pk('relations')])!==relationId||!block.isConnected)return;const rows=Array.isArray(data.rows)?data.rows:[];block.querySelector('.related-grid').innerHTML=rows.length?rows.map(project=>'<a class="rel-card" href="projects.php?id='+Number(project.ProjectID)+'">'+esc(project.Naam)+' · '+esc(project.Status||'')+'</a>').join(''):'<div class="empty">Geen gekoppelde projecten.</div>'}).catch(()=>{if(block.isConnected)block.querySelector('.related-grid').innerHTML='<div class="empty">Projecten konden niet worden geladen.</div>'})};
// Extra onderhoudsplanfuncties staan buiten het gewone bewerkformulier: ze zijn
// daardoor ook direct vanuit het detailscherm beschikbaar.
async function maintenanceExtraRequest(planId,action,body){const opts={method:'POST',headers:{'X-CSRF-Token':meta.csrf}};if(body instanceof FormData)opts.body=body;else{opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(body||{})}const response=await fetch('maintenance_extra_api.php?action='+encodeURIComponent(action)+'&id='+encodeURIComponent(planId),{...opts,credentials:'same-origin',cache:'no-store'});const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.error||'Opslaan mislukt.');return data}
function maintenanceExtraError(error){const box=document.getElementById('maintenanceExtras');if(box)box.insertAdjacentHTML('afterbegin','<div class="err">'+esc(error.message||String(error))+'</div>')}
async function maintenanceExtraLoad(planId){const box=document.getElementById('maintenanceExtras');if(!box)return;try{const response=await fetch('maintenance_extra_api.php?action=list&id='+encodeURIComponent(planId),{credentials:'same-origin',cache:'no-store'});const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.error||'Gegevens laden mislukt.');if(!box.isConnected||String(selected?.[pk('maintenance_plans')])!==String(planId))return;const admin=USER_ROLE==='admin';const opts=(meta.maintenanceOptions?.relations||[]).filter(x=>!data.relations.some(r=>String(r.RelatieID)===String(x.id))).map(x=>'<option value="'+esc(String(x.id))+'">'+esc(x.label)+'</option>').join('');let h='<div class="section"><div class="section-head">👷 Uitvoerende firma’s / relaties</div><div class="pad">';h+=data.relations.length?'<ul>'+data.relations.map(r=>'<li><a href="#" data-entity="relations" data-id="'+esc(String(r.RelatieID))+'" onclick="event.preventDefault();openMaintenanceRelated(this)">'+esc(r.Naam)+'</a>'+(admin?' <button type="button" class="btn" onclick="maintenanceExtraChange('+planId+',\'unlink_relation\',{RelatieID:'+Number(r.RelatieID)+'})" title="Ontkoppelen">×</button>':'')+'</li>').join('')+'</ul>':'<span class="muted">Geen extra uitvoerders gekoppeld.</span>';if(admin)h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><select id="maintenanceRelationSelect" style="max-width:400px"><option value="">Selecteer uitvoerende firma…</option>'+opts+'</select><button type="button" class="btn" onclick="maintenanceExtraLinkRelation('+planId+')">🔗 Koppelen</button></div>';h+='</div></div>';
h+='<div class="section"><div class="section-head">📷 Foto’s</div><div class="pad"><div style="display:flex;gap:10px;flex-wrap:wrap">'+data.photos.map(p=>'<div><a href="maintenance_photo.php?id='+Number(p.FotoID)+'" target="_blank" rel="noopener"><img src="maintenance_photo.php?id='+Number(p.FotoID)+'" alt="'+esc(p.Bestandsnaam)+'" style="width:160px;height:120px;object-fit:cover;border:1px solid #d5e0e8;border-radius:6px"></a>'+(admin?'<br><button type="button" class="btn" data-delete-photo="'+Number(p.FotoID)+'" onclick="maintenanceExtraDeletePhoto(this,'+planId+','+Number(p.FotoID)+')">× Verwijderen</button>':'')+'</div>').join('')+'</div>';if(!data.photos.length)h+='<div class="muted">Nog geen foto’s toegevoegd.</div>';if(admin)h+='<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px"><input id="maintenancePhotoInput" type="file" accept="image/jpeg,image/png,image/webp"><button type="button" class="btn" onclick="maintenanceExtraUploadPhoto('+planId+')">⬆ Foto toevoegen</button></div>';h+='</div></div>';
h+='<div class="section"><div class="section-head">✅ Actiepunten</div><div class="pad"><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th>Actie</th><th>Verantwoordelijk</th><th>Gereed op</th><th>Status</th>'+(admin?'<th>Acties</th>':'')+'</tr></thead><tbody>';for(const a of data.actions){const aid=Number(a.ActieID);h+='<tr data-maintenance-action="'+aid+'"><td>'+(admin?'<input data-field="Actie" value="'+esc(a.Actie)+'" aria-label="Actie">':esc(a.Actie))+'</td><td>'+(admin?'<input data-field="Verantwoordelijk" value="'+esc(a.Verantwoordelijk||'')+'" aria-label="Verantwoordelijke">':esc(a.Verantwoordelijk||'—'))+'</td><td>'+(admin?'<input type="date" data-field="DatumCompleet" value="'+esc(a.DatumCompleet||'')+'" aria-label="Gereed op">':esc(a.DatumCompleet||'—'))+'</td><td>'+(admin?'<label><input type="checkbox" data-field="Compleet" '+(Number(a.Compleet)?'checked':'')+'> Gereed</label>':(Number(a.Compleet)?'Gereed':'Open'))+'</td>'+(admin?'<td><button type="button" class="btn" onclick="maintenanceExtraSaveAction('+planId+','+aid+')">💾</button> <button type="button" class="btn danger" onclick="maintenanceExtraDeleteAction(this,'+planId+','+aid+')">×</button></td>':'')+'</tr>'}if(admin)h+='<tr data-maintenance-action="new"><td><input data-field="Actie" placeholder="Nieuw actiepunt" aria-label="Nieuw actiepunt"></td><td><input data-field="Verantwoordelijk" placeholder="Verantwoordelijke" aria-label="Verantwoordelijke"></td><td><input type="date" data-field="DatumCompleet" aria-label="Gereed op"></td><td><label><input type="checkbox" data-field="Compleet"> Gereed</label></td><td><button type="button" class="btn" onclick="maintenanceExtraSaveAction('+planId+',0)">＋ Toevoegen</button></td></tr>';h+='</tbody></table></div></div></div>';box.innerHTML=h}catch(e){box.innerHTML='<div class="err">'+esc(e.message)+'</div>'}}
async function maintenanceExtraChange(planId,action,body){try{await maintenanceExtraRequest(planId,action,body);await maintenanceExtraLoad(planId)}catch(e){maintenanceExtraError(e)}}
function maintenanceExtraLinkRelation(planId){const rid=Number(document.getElementById('maintenanceRelationSelect')?.value||0);if(rid)maintenanceExtraChange(planId,'link_relation',{RelatieID:rid})}
async function maintenanceExtraUploadPhoto(planId){const file=document.getElementById('maintenancePhotoInput')?.files?.[0];if(!file)return;const body=new FormData();body.append('photo',file);await maintenanceExtraChange(planId,'upload_photo',body)}
function maintenanceExtraSaveAction(planId,aid){const row=document.querySelector('[data-maintenance-action="'+(aid||'new')+'"]');if(!row)return;const value=name=>row.querySelector('[data-field="'+name+'"]');maintenanceExtraChange(planId,'save_action',{ActieID:aid,Actie:value('Actie').value,Verantwoordelijk:value('Verantwoordelijk').value,DatumCompleet:value('DatumCompleet').value,Compleet:value('Compleet').checked})}
function maintenanceExtraDeleteAction(button,planId,aid){if(button.dataset.armed!=='1'){button.dataset.armed='1';button.textContent='Bevestig wissen';setTimeout(()=>{if(button.isConnected){button.dataset.armed='0';button.textContent='×'}},8000);return}maintenanceExtraChange(planId,'delete_action',{ActieID:aid})}
function maintenanceExtraDeletePhoto(button,planId,fid){if(button.dataset.armed!=='1'){button.dataset.armed='1';button.textContent='Bevestig wissen';setTimeout(()=>{if(button.isConnected){button.dataset.armed='0';button.textContent='× Verwijderen'}},8000);return}maintenanceExtraChange(planId,'delete_photo',{FotoID:fid})}
const showMaintenanceDetailBase=showMaintenanceDetail;
function maintenanceRenderMjopLink(row){const value=String(row?.MJOPReferentie??'').trim();if(!value)return;const option=(meta.maintenanceOptions?.mjop||[]).find(x=>String(x.code??x.id)===value);if(!option)return;const field=[...$('detail').querySelectorAll('.view-field')].find(x=>x.querySelector('label')?.textContent?.trim()==='MJOP referentie');const target=field?.querySelector('.view-value');if(!target)return;target.textContent='';const link=document.createElement(option.url?'a':'span');link.textContent=option.label;if(option.url){link.href=option.url;link.target='_blank';link.rel='noopener';link.title='Open MJOP op pagina '+option.page}target.append(link)}
showMaintenanceDetail=async function(row){await showMaintenanceDetailBase(row);if(currentEntity!=='maintenance_plans'||!selected)return;maintenanceRenderMjopLink(row);const id=row[pk('maintenance_plans')];const related=[...$('detail').querySelectorAll('.section')].find(section=>section.querySelector('.section-head')?.textContent?.includes('Gekoppelde gegevens'));related?.querySelectorAll('.rel-card')[1]?.remove();const actions=$('detail').querySelector('.actions');const extra=document.createElement('div');extra.id='maintenanceExtras';extra.innerHTML='<div class="empty">Actiepunten, uitvoerders en foto’s laden…</div>';if(actions)actions.before(extra);else $('detail').append(extra);$('detail').insertAdjacentHTML('afterbegin','<div class="actions" style="justify-content:flex-start"><a class="btn" href="maintenance_export_pdf.php?id='+encodeURIComponent(id)+'" download>⬇ Werkopdracht / PDF</a></div>');await maintenanceExtraLoad(id)};
init();syncListHeader();
</script>
<div id="assetLightbox" class="asset-lightbox" role="dialog" aria-modal="true" aria-hidden="true"
     onclick="if(event.target===this)closeAssetImage()">
  <div class="asset-lightbox-card" id="assetLightboxCard">
    <div class="asset-lightbox-toolbar">
      <span id="assetLightboxCaption" class="asset-lightbox-caption"></span>
      <div class="asset-lightbox-controls">
        <button type="button" class="asset-lightbox-small" onclick="assetImageSmaller()" aria-label="Afbeelding kleiner">− Kleiner</button>
        <button type="button" class="asset-lightbox-reset" onclick="assetImageReset()" aria-label="Normale grootte">100%</button>
        <button type="button" class="asset-lightbox-close" onclick="closeAssetImage()" aria-label="Sluiten">×</button>
      </div>
    </div>
    <div class="asset-lightbox-body">
      <img id="assetLightboxImg" alt="">
    </div>
  </div>
</div>
<script>
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeAssetImage()});
let assetLightboxScale=1;
function openAssetImage(url,title){
  let lb=document.getElementById('assetLightbox');
  const img=document.getElementById('assetLightboxImg');
  const cap=document.getElementById('assetLightboxCaption');
  if(!lb||!img||!cap)return;
  img.src=url; img.alt=title||'Afbeelding'; cap.textContent=title||'';
  assetLightboxScale=1; applyAssetLightboxScale();
  lb.classList.add('open'); lb.setAttribute('aria-hidden','false');
}
function applyAssetLightboxScale(){
  const img=document.getElementById('assetLightboxImg');
  if(img)img.style.transform='scale('+assetLightboxScale+')';
}
function assetImageSmaller(){
  assetLightboxScale=Math.max(.25,assetLightboxScale-.15);
  applyAssetLightboxScale();
}
function assetImageReset(){
  assetLightboxScale=1; applyAssetLightboxScale();
}
function closeAssetImage(){
  const lb=document.getElementById('assetLightbox'); if(!lb)return;
  lb.classList.remove('open'); lb.setAttribute('aria-hidden','true');
  const img=document.getElementById('assetLightboxImg'); if(img){img.src='';img.style.transform='scale(1)'}
}
const renderRelatedCore=renderRelated;
renderRelated=function(entity,x){
  if(entity==='relations'&&selected){
    const relationId=String(selected[pk('relations')]??'');
    const stale=(x.addresses||[]).some(address=>{const key=findKey(address,['RelatieID','relatie_id']);return key&&String(address[key]??'')!==relationId});
    if(stale)return;
  }
  renderRelatedCore(entity,x);
  if(entity==='relations'&&USER_ROLE==='admin'&&!document.querySelector('[data-new-relation-address]')){
    const related=$('related');
    if(related)related.insertAdjacentHTML('beforeend','<div class="actions"><button class="btn primary small" data-new-relation-address type="button" onclick="newRelatedRecord(\'addresses\')">＋ Nieuw adres</button></div>');
  }
};
document.addEventListener('change',e=>{if(e.target&&e.target.id==='meetingFileInput'){const b=e.target.parentElement?.querySelector('button');if(b)b.disabled=!e.target.files.length}});
document.addEventListener("change",e=>{
  if(e.target&&e.target.id==="assetImageInput"){
    const b=document.querySelector("[data-upload-asset-images]");
    if(b)b.disabled=!e.target.files.length;
  }
});
const renderAssetRelatedWithoutProjects=renderAssetRelated;
renderAssetRelated=async function(id){
  await renderAssetRelatedWithoutProjects(id);
  const box=$('related');if(!box)return;
  try{
    const response=await fetch('project_api.php?action=asset_projects&id='+encodeURIComponent(id),{credentials:'same-origin',cache:'no-store'});
    const data=await response.json();if(!data.ok)throw new Error(data.error||'Projecten niet beschikbaar');
    const html='<div class="related-head">📋 Projecten</div>'+(data.rows.length?'<ul class="link-list">'+data.rows.map(p=>'<li><a href="projects.php?id='+encodeURIComponent(p.ProjectID)+'">'+esc(p.Naam)+'</a> · '+esc(p.Status)+'</li>').join('')+'</ul>':'<div class="empty">Geen gekoppelde projecten.</div>');
    box.insertAdjacentHTML('beforeend',html);
  }catch(e){box.insertAdjacentHTML('beforeend','<div class="related-head">📋 Projecten</div><div class="empty">Projectkoppelingen zijn tijdelijk niet beschikbaar.</div>')}
};
window.addEventListener('load',async()=>{
  const params=new URLSearchParams(location.search),module=params.get('module'),id=params.get('id');
  if(module){const button={contacts:'navContacts',relations:'navRelations',Activa:'navAssets',maintenance_plans:'navMaintenance',meetings:'navMeetings',Sleutels:'navKeys'}[module];if(button){await showListTab(module,$(button));if(module==='Activa'&&id)await selectAsset(id)}}
});
</script>
</body></html>
